window.FATAWA={"title":"الفتاوى الميسّرة","subtitle":"في ضوء الكتاب والسنة","author":"عبد الحسيب منيب الأفغاني","email":"","fatawa":[{"n":1,"bab":"الطهارة","sub":"المياه","title":"الوضوء والغسل بماء البحر","q":"هل يجوز الوضوء والغسل بماء البحر مع ملوحته؟","short":"نعم، ماء البحر طهور، يُتوضأ به ويُغتسل، ولا تضرّه ملوحته؛ وهذا قول عامة أهل العلم، ومنهم الأئمة الأربعة.","body":[{"t":"h","text":"صورة المسألة"},{"t":"p","text":"ماء البحر ماء باقٍ على أصل خلقته، وإنما تغيّر طعمه بالملوحة التي خُلق عليها؛ فهل يخرجه ذلك عن كونه ماءً مطلقًا يُتطهَّر به؟"},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"أنه طهور يُتوضأ به ويُغتسل كسائر المياه، وهو قول عامة أهل العلم."},{"t":"p","text":"ودليلهم عموم قوله تعالى:"},{"t":"aya","text":"وَأَنزَلْنَا مِنَ ٱلسَّمَآءِ مَآءً طَهُورًا","ref":"الفرقان: ٤٨"},{"t":"p","text":"ونصُّ السنة الصريح فيه:"},{"t":"quote","text":"عَنْ أَبِي هُرَيْرَةَ - رَضِيَ اللَّهُ عَنْهُ - قَالَ: «سَأَلَ رَجُلٌ رَسُولَ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - فَقَالَ: يَا رَسُولَ اللَّهِ إنَّا نَرْكَبُ الْبَحْرَ، وَنَحْمِلُ مَعَنَا الْقَلِيلَ مِنْ الْمَاءِ، فَإِنْ تَوَضَّأْنَا بِهِ عَطِشْنَا، أَفَنَتَوَضَّأُ، بِمَاءِ الْبَحْرِ؟ فَقَالَ رَسُولُ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -: هُوَ الطَّهُورُ مَاؤُهُ، الْحِلُّ مَيْتَتُهُ","src":"نيل الأوطار","loc":"١/٢٧"},{"t":"quote","text":"أَخْرَجَهُ الْأَرْبَعَةُ، وَابْنُ أَبِي شَيْبَةَ، وَاللَّفْظُ لَهُ، وَصَحَّحَهُ ابْنُ خُزَيْمَةَ وَالتِّرْمِذِيُّ، وَرَوَاهُ مَالِكٌ وَالشَّافِعِيُّ وَأَحْمَدُ","src":"سبل السلام","loc":"١/١٩","pre":"وفي تخريجه قال الصنعاني:"},{"t":"quote","text":"وَرُوِيَ عَنْ عُمَرَ - رَضِيَ اللَّهُ عَنْهُ - أَنَّهُ قَالَ: \" مَنْ لَمْ يُطَهِّرْهُ مَاءُ الْبَحْرِ فَلَا طَهَّرَهُ اللَّهُ \" وَلِأَنَّهُ مَاءٌ بَاقٍ عَلَى أَصِلْ خِلْقَتِهِ، فَجَازَ الْوُضُوءُ بِهِ كَالْعَذْبِ","src":"المغني","loc":"١/٩","pre":"وقال ابن قدامة:"},{"t":"qawl","label":"القول الثاني","text":"كراهة التطهّر به، وأن التيمم أحب منه، وهو مرويّ عن عبد الله بن عمر وعبد الله بن عمرو رضي الله عنهم، وعن سعيد بن المسيب."},{"t":"quote","text":"إلَّا أَنَّهُ حُكِيَ عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ وَعَبْدِ اللَّهِ بْنِ عَمْرٍو، أَنَّهُمَا قَالَا فِي الْبَحْرِ: التَّيَمُّمُ أَعْجَبُ إلَيْنَا مِنْهُ. هُوَ نَارٌ. وَحَكَاهُ الْمَاوَرْدِيُّ عَنْ سَعِيدِ بْنِ الْمُسَيِّبِ","src":"المغني","loc":"١/٩","pre":"قال ابن قدامة:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الراجح القول الأول بلا تردد؛ لأن الحديث صحيح صريح في محل السؤال نفسه، ولأن الله تعالى لم يأذن بالتيمم إلا عند فقد الماء، وماء البحر ماء."},{"t":"quote","text":"وَالْأَوَّلُ أَوْلَى، لِقَوْلِ اللَّهِ تَعَالَى: {فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا} النساء: 43 وَمَاءُ الْبَحْرِ مَاءٌ، لَا يَجُوزُ الْعُدُولُ إلَى التَّيَمُّمِ مَعَ وُجُودِهِ","src":"المغني","loc":"١/٩","pre":"قال ابن قدامة:"},{"t":"quote","text":"وَقَوْلُهُمْ: \" هُوَ نَارٌ \" إنْ أُرِيدَ بِهِ أَنَّهُ نَارٌ فِي الْحَالِ فَهُوَ خِلَافُ الْحِسِّ، وَإِنْ أُرِيدَ أَنَّهُ يَصِيرُ نَارًا، لَمْ يَمْنَعْ ذَلِكَ الْوُضُوءَ بِهِ حَالَ كَوْنِهِ مَاءً","src":"المغني","loc":"١/٩"},{"t":"quote","text":"وَأَجْمَعَ الْعُلَمَاءُ عَلَى أَنَّ جَمِيعَ أَنْوَاعِ الْمِيَاهِ طَاهِرَةٌ فِي نَفْسِهَا مُطَهِّرَةٌ لِغَيْرِهَا، إِلَّا مَاءَ الْبَحْرِ، فَإِنَّ فِيهِ خِلَافًا فِي الصَّدْرِ الْأَوَّلِ شَاذًّا. وَهُمْ مَحْجُوجُونَ بِتَنَاوُلِ اسْمِ الْمَاءِ الْمُطْلَقِ لَهُ، وَبِالْأَثَرِ الَّذِي خَرَّجَهُ مَالِكٌ وَهُوَ قَوْلُهُ - عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ - «هُوَ الطَّهُورُ مَاؤُهُ الْحِلُّ مِيتَتُهُ» وَهُوَ وَإِنْ كَانَ حَدِيثًا مُخْتَلَفًا فِي صِحَّتِهِ، فَظَاهِرُ الشَّرْعِ يُعَضِّدُهُ","src":"بداية المجتهد","loc":"١/٢٩-٣٠","pre":"ولهذا حكى ابن رشد الاتفاق فقال:"}],"refs":["نيل الأوطار (١/٢٧)","سبل السلام (١/١٩)","المغني (١/٩)","بداية المجتهد (١/٢٩-٣٠)"],"related":["الماء المتغير بطول المكث أو بالطحلب","الماء الذي خالطه شيء طاهر فغيّره"],"alts":["ماء البحر طاهر","الوضوء بالماء المالح","الاغتسال في البحر"]},{"n":2,"bab":"الطهارة","sub":"المياه","title":"الماء المتغير بطول المكث أو بالطحلب","q":"ماءٌ في خزان أو بركة تغيّر لونه أو رائحته بطول بقائه أو بالطحالب وأوراق الشجر، فهل يُتوضأ به؟","short":"نعم، يجوز الوضوء به عند عامة أهل العلم؛ لأن ما يغيّر الماء مما لا يُستطاع الاحتراز منه غالبًا لا يسلبه الطهورية، ما لم يكن التغير بنجاسة.","body":[{"t":"h","text":"صورة المسألة"},{"t":"p","text":"يتغيّر الماء أحيانًا بلا نجاسة: إما بطول مكثه في مكانه — وهو الماء الآجن — وإما بما ينبت فيه أو يسقط فيه من غير قصد، كالطحلب وورق الشجر والتراب الذي يجري عليه."},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"أنه باقٍ على طهوريته، يُتوضأ به بلا كراهة، وهو قول جماهير أهل العلم."},{"t":"quote","text":"وَكَذَلِكَ أَجْمَعُوا عَلَى أَنَّ كُلَّ مَا يُغَيِّرُ الْمَاءَ مِمَّا لَا يَنْفَكُّ عَنْهُ غَالِبًا أَنَّهُ لَا يَسْلُبُهُ صِفَةَ الطَّهَارَةِ وَالتَّطْهِيرِ إِلَّا خِلَافًا شَاذًّا رُوِيَ فِي الْمَاءِ الْآجِنِ عَنِ ابْنِ سِيرِينَ، وَهُوَ أَيْضًا مَحْجُوجٌ بِتَنَاوُلِ اسْمِ الْمَاءِ الْمُطْلَقِ لَهُ","src":"بداية المجتهد","loc":"١/٣٠","pre":"قال ابن رشد:"},{"t":"quote","text":"الثَّانِي: مَا لَا يُمْكِنُ التَّحَرُّزُ مِنْهُ، كَالطُّحْلُبِ وَالْخَزِّ وَسَائِرِ مَا يَنْبُتُ فِي الْمَاءِ، وَكَذَلِكَ وَرَقُ الشَّجَرِ الَّذِي يَسْقُطُ فِي الْمَاءِ، أَوْ تَحْمِلُهُ الرِّيحُ فَتُلْقِيهِ فِيهِ، وَمَا تَجْذِبُهُ السُّيُولُ مِنْ الْعِيدَانِ وَالتِّبْنِ وَنَحْوِهِ، فَتُلْقِيهِ فِي الْمَاءِ، وَمَا هُوَ فِي قَرَارِ الْمَاءِ كَالْكِبْرِيتِ وَالْقَارِ وَغَيْرِهِمَا، إذَا جَرَى عَلَيْهِ الْمَاءُ فَتَغَيَّرَ بِهِ، أَوْ كَانَ فِي الْأَرْضِ الَّتِي يَقِفُ فِيهَا الْمَاءُ. فَهَذَا كُلُّهُ يُعْفَى عَنْهُ؛ لِأَنَّهُ يَشُقُّ التَّحَرُّزُ مِنْهُ، فَإِنْ أُخِذَ شَيْءٌ مِنْ ذَلِكَ وَأُلْقِيَ فِي الْمَاءِ وَغَيْرِهِ كَانَ حُكْمُهُ حُكْمَ مَا أَمْكَنَ التَّحَرُّزُ مِنْهُ، مِنْ الزَّعْفَرَانِ وَنَحْوِهِ؛ لِأَنَّ الِاحْتِرَازَ مِنْهُ مُمْكِنٌ","src":"المغني","loc":"١/١٢","pre":"وقال ابن قدامة في أنواع الماء المضاف الذي يجوز الوضوء به:"},{"t":"qawl","label":"القول الثاني","text":"كراهة الوضوء بالماء الآجن، وهو قول محمد بن سيرين وحده."},{"t":"quote","text":"وَالْمَاءُ الْآجِنُ، وَهُوَ الَّذِي يَتَغَيَّرُ بِطُولِ مُكْثِهِ فِي الْمَكَانِ، مِنْ غَيْرِ مُخَالَطَةِ شَيْءٍ يُغَيِّرُهُ، بَاقٍ عَلَى إطْلَاقِهِ فِي قَوْلِ أَكْثَرِ أَهْلِ الْعِلْمِ، قَالَ ابْنُ الْمُنْذِرِ: أَجْمَعَ كُلُّ مَنْ نَحْفَظُ قَوْلَهُ مِنْ أَهْلِ الْعِلْمِ عَلَى أَنَّ الْوُضُوءَ بِالْمَاءِ الْآجِنِ مِنْ غَيْرِ نَجَاسَةٍ حَلَّتْ فِيهِ جَائِزٌ، غَيْرَ ابْنِ سِيرِينَ فَإِنَّهُ كَرِهَ ذَلِكَ","src":"المغني","loc":"١/١٢","pre":"قال ابن قدامة:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الراجح قول الجمهور؛ لأن هذا التغير لا ينفك عنه الماء في العادة، ولا يُخرجه عن اسم الماء المطلق."},{"t":"quote","text":"وَقَوْلُ الْجُمْهُورِ أُولَى، فَإِنَّهُ يُرْوَى «أَنَّ النَّبِيَّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - تَوَضَّأَ مِنْ بِئْرٍ كَأَنَّ مَاءَهُ نُقَاعَةُ الْحِنَّاءِ» وَلِأَنَّهُ تَغَيَّرَ مِنْ غَيْرِ مُخَالَطَةٍ","src":"المغني","loc":"١/١٢","pre":"قال ابن قدامة:"},{"t":"tanbih","items":[{"t":"p","text":"إذا أُلقي الطحلب أو الورق في الماء قصدًا حتى غيّره، فحكمه حكم الماء الذي خالطه شيء طاهر (انظر الفتوى رقم ٣)، كما في كلام ابن قدامة المنقول آنفًا."},{"t":"p","text":"وإذا كان تغيّر الماء بنجاسة لم يجز الوضوء به، وهذا باب آخر (انظر الفتوى رقم ٥)."}]}],"refs":["بداية المجتهد (١/٣٠)","المغني (١/١٢)"],"related":["الماء الذي خالطه شيء طاهر فغيّره","الماء القليل تقع فيه نجاسة ولم يتغير"],"alts":["الماء الآسن","ماء الخزان المتغير","الطحالب في الماء"]},{"n":3,"bab":"الطهارة","sub":"المياه","title":"الماء الذي خالطه شيء طاهر فغيّره","q":"هل يجوز الوضوء بماء خالطه صابون أو زعفران أو نحوهما فتغيّر لونه أو ريحه؟","short":"إن بقي اسم الماء عليه ورقّته وجريانه — كماء قليلِ الصابون أو السدر — جاز الوضوء به على الراجح، وهو مذهب الحنفية ورواية عن أحمد؛ وإن غلب عليه المخالط حتى صار يسمّى باسم آخر — كالشاي والحبر وماء الورد — لم يجز بالاتفاق.","body":[{"t":"h","text":"تحرير محل النزاع"},{"t":"p","text":"اتفق العلماء على طرفين في هذه المسألة، واختلفوا فيما بينهما:"},{"t":"quote","text":"وَلَا نَعْلَمُ خِلَافًا بَيْنَ أَهْلِ الْعِلْمِ فِي جَوَازِ الْوُضُوءِ بِمَاءٍ خَالَطَهُ طَاهِرٌ، لَمْ يُغَيِّرْهُ، إلَّا مَا حُكِيَ عَنْ أُمِّ هَانِئٍ، فِي مَاءٍ بُلَّ فِيهِ خُبْزٌ: لَا يُتَوَضَّأُ بِهِ. وَلَعَلَّهَا أَرَادَتْ مَا تَغَيَّرَ بِهِ","src":"المغني","loc":"١/١٣","pre":"الطرف الأول — ما لم يتغير بالمخالط: قال ابن قدامة:"},{"t":"quote","text":"أَحَدُهَا، مَا اُعْتُصِرَ مِنْ الطَّاهِرَاتِ كَمَاءِ الْوَرْدِ، وَمَاءِ الْقَرَنْفُلِ، وَمَا يَنْزِلُ مِنْ عُرُوقِ الشَّجَرِ إذَا قُطِعَتْ رَطْبَةً. الثَّانِي، مَا خَالَطَهُ طَاهِرٌ فَغَيَّرَ اسْمَهُ، وَغَلَبَ عَلَى أَجْزَائِهِ، حَتَّى صَارَ صِبْغًا، أَوْ حِبْرًا، أَوْ خَلًّا، أَوْ مَرَقًا، وَنَحْوَ ذَلِكَ. الثَّالِثُ، مَا طُبِخَ فِيهِ طَاهِرٌ فَتَغَيَّرَ بِهِ، كَمَاءِ الْبَاقِلَّا الْمَغْلِيِّ. فَجَمِيعُ هَذِهِ الْأَنْوَاعِ لَا يَجُوزُ الْوُضُوءُ بِهَا، وَلَا الْغُسْلُ، لَا نَعْلَمُ فِيهِ خِلَافًا، إلَّا مَا حُكِيَ عَنْ ابْنِ أَبِي لَيْلَى وَالْأَصَمِّ فِي الْمِيَاهِ الْمُعْتَصَرَةِ، أَنَّهَا طَهُورٌ يَرْتَفِعُ بِهَا الْحَدَثُ، وَيُزَالُ بِهَا النَّجَسُ","src":"المغني","loc":"١/١١","pre":"الطرف الثاني — ما غلب عليه المخالط حتى زال عنه اسم الماء: قال ابن قدامة:"},{"t":"p","text":"وأما محل الخلاف: فهو الماء الذي غيّر المخالطُ الطاهر أحدَ أوصافه، وبقي مع ذلك يسمّى ماءً."},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"أنه طاهر غير مطهِّر، فلا يرفع الحدث، وهو قول مالك والشافعي وإسحاق، ورواية عن أحمد."},{"t":"quote","text":"وَاخْتَلَفَ أَهْلُ الْعِلْمِ فِي الْوُضُوءِ بِهِ، وَاخْتَلَفْت الرِّوَايَةُ عَنْ إمَامِنَا، - رَحِمَهُ اللَّهُ -، فِي ذَلِكَ؛ فَرُوِيَ عَنْهُ: لَا تَحْصُلُ الطَّهَارَةُ بِهِ. وَهُوَ قَوْلُ مَالِكٍ وَالشَّافِعِيِّ وَإِسْحَاقَ وَقَالَ الْقَاضِي أَبُو يَعْلَى وَهِيَ أَصَحُّ، وَهِيَ الْمَنْصُورَةُ عِنْدَ أَصْحَابِنَا فِي الْخِلَافِ","src":"المغني","loc":"١/١١","pre":"قال ابن قدامة:"},{"t":"quote","text":"وَوَجْهُ الْأُولَى: أَنَّهُ مَاءٌ تَغَيَّرَ بِمُخَالَطَةِ مَا لَيْسَ بِطَهُورٍ يُمْكِنُ الِاحْتِرَازُ مِنْهُ، فَلَمْ يَجُزْ الْوُضُوءُ بِهِ، كَمَاءِ الْبَاقِلَّا الْمَغْلِيِّ؛ وَلِأَنَّهُ زَالَ عَنْ إطْلَاقِهِ، فَأَشْبَهَ الْمَغْلِيَّ","src":"المغني","loc":"١/١١","pre":"ودليلهم:"},{"t":"qawl","label":"القول الثاني","text":"أنه طهور يُتوضأ به ما دام اسم الماء باقيًا عليه، وهو مذهب أبي حنيفة وأصحابه، ورواية عن أحمد نقلها جماعة من أصحابه."},{"t":"quote","text":"وَنَقَلَ عَنْ أَحْمَدَ جَمَاعَةٌ مِنْ أَصْحَابِهِ، مِنْهُمْ أَبُو الْحَارِثِ، وَالْمَيْمُونِيُّ، وَإِسْحَاقُ بْنُ مَنْصُورٍ، جَوَازَ الْوُضُوءِ بِهِ. وَهَذَا مَذْهَبُ أَبِي حَنِيفَةَ وَأَصْحَابِهِ؛ لِأَنَّ اللَّهَ تَعَالَى قَالَ: {فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا} النساء: 43 وَهَذَا عَامٌّ فِي كُلِّ مَاءٍ؛ لِأَنَّهُ نَكِرَةٌ فِي سِيَاقِ النَّفْيِ، وَالنَّكِرَةُ فِي سِيَاقِ النَّفْي تَعُمُّ، فَلَا يَجُوزُ التَّيَمُّمُ مَعَ وُجُودِهِ، وَأَيْضًا قَوْلُ النَّبِيِّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - فِي حَدِيثِ أَبِي ذَرٍّ: «التُّرَابُ كَافِيكَ مَا لَمْ تَجِدْ الْمَاءَ» . وَهَذَا وَاجِدٌ لِلْمَاءِ؛ وَلِأَنَّ النَّبِيَّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - وَأَصْحَابَهُ كَانُوا يُسَافِرُونَ، وَغَالِبُ أَسْقِيَتِهِمْ الْأُدْمُ، وَالْغَالِبُ أَنَّهَا تُغَيِّرُ الْمَاءَ، فَلَمْ يُنْقَلْ عَنْهُمْ تَيَمُّمٌ مَعَ وُجُودِ شَيْءٍ مِنْ تِلْكَ الْمِيَاهِ؛ وَلِأَنَّهُ طَهُورٌ خَالَطَهُ طَاهِرٌ لَمْ يَسْلُبْهُ اسْمَ الْمَاءِ، وَلَا رِقَّتَهُ، وَلَا جَرَيَانَهُ، فَأَشْبَهَ الْمُتَغَيِّرَ بِالدُّهْنِ","src":"المغني","loc":"١/١١","pre":"قال ابن قدامة:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الراجح — والله أعلم — القول الثاني؛ لأن الله تعالى علّق التيمم بعدم الماء، وهذا ماء، ولأن النبي ﷺ أمر بغسل الميت بماء وسدر، ومعلوم أن السدر يغيّر الماء."},{"t":"quote","text":"وَالْحَقُّ أَنَّ الِاخْتِلَاطَ يَخْتَلِفُ بِالْكَثْرَةِ وَالْقِلَّةِ، فَقَدْ يَبْلُغُ مِنَ الْكَثْرَةِ إِلَى حَدٍّ لَا يَتَنَاوَلُهُ اسْمُ الْمَاءِ الْمُطْلَقِ مِثْلَ مَا يُقَالُ مَاءُ الْغُسْلِ، وَقَدْ لَا يَبْلُغُ إِلَى ذَلِكَ الْحَدِّ، وَبِخَاصَّةٍ مَتَى تَغَيَّرَتْ مِنْهُ الرِّيحُ فَقَطْ، وَلِذَلِكَ لَمْ يَعْتَبِرِ الرِّيحَ قَوْمٌ مِمَّنْ مَنَعُوا الْمَاءَ الْمُضَافَ، وَقَدْ قَالَ - عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ - لِأُمِّ عَطِيَّةَ عِنْدَ أَمْرِهِ إِيَّاهَا بِغَسْلِ ابْنَتِهِ: «اغْسِلْنَهَا بِمَاءٍ وَسِدْرٍ وَاجْعَلْنَ فِي الْأَخِيرَةِ كَافُورًا أَوْ شَيْئًا مِنْ كَافُورٍ» فَهَذَا مَاءٌ مُخْتَلِطٌ وَلَكِن لَمْ يَبْلُغْ مِنْ الِاخْتِلَاطِ بِحَيْثُ يُسْلَبُ عَنْهُ اسْمُ الْمَاءِ الْمُطْلَقِ، وَقَدْ رُوِيَ عَنْ مَالِكٍ اعْتِبَارُ الْكَثْرَةِ فِي الْمُخَالَطَةِ وَالْقِلَّةِ وَالْفَرْقِ بَيْنَهُمَا، فَأَجَازَهُ مَعَ الْقِلَّةِ وَإِنْ ظَهَرَتِ الْأَوْصَافُ، وَلَمْ يُجِزْهُ مَعَ الْكَثْرَةِ","src":"بداية المجتهد","loc":"١/٣٣","pre":"قال ابن رشد:"},{"t":"quote","text":"عَنْ أُمِّ عَطِيَّةَ قَالَتْ: «دَخَلَ عَلَيْنَا رَسُولُ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - حِينَ تُوُفِّيَتْ ابْنَتُهُ، فَقَالَ: اغْسِلْنَهَا ثَلَاثًا أَوْ خَمْسًا أَوْ أَكْثَرَ مِنْ ذَلِكَ إنْ رَأَيْتُنَّ بِمَاءٍ وَسِدْرٍ، وَاجْعَلْنَ فِي الْأَخِيرَةِ كَافُورًا أَوْ شَيْئًا مِنْ كَافُورٍ، فَإِذَا فَرَغْتُنَّ فَآذِنَّنِي، فَلَمَّا فَرَغْنَا آذَنَّاهُ، فَأَعْطَانَا حَقْوَهُ، فَقَالَ: أَشْعِرْنَهَا إيَّاهُ، يَعْنِي إزَارَهُ» رَوَاهُ الْجَمَاعَةُ وَفِي رِوَايَةٍ لَهُمْ «ابْدَأْنَ بِمَيَامِنِهَا وَمَوَاضِعِ الْوُضُوءِ مِنْهَا» ، وَفِي لَفْظٍ «اغْسِلْنَهَا وِتْرًا ثَلَاثًا أَوْ خَمْسًا أَوْ سَبْعًا أَوْ أَكْثَرَ مِنْ ذَلِكَ إنْ رَأَيْتُنَّ» وَفِيهِ قَالَتْ: «فَضَفَرْنَا شَعْرَهَا ثَلَاثَةَ قُرُونٍ فَالْقَيْنَاهَا خَلْفَهَا» مُتَّفَقٌ عَلَيْهِمَا","src":"نيل الأوطار","loc":"٤/٣٩","pre":"وحديث أم عطية في تغسيل ابنة النبي ﷺ:"},{"t":"tanbih","items":[{"t":"p","text":"فالضابط في هذا الباب: بقاء اسم الماء المطلق؛ فما دام الناس يسمّونه ماءً جاز التطهّر به، فإذا صار يسمّى باسم المخالط — شايًا أو مرقًا أو عصيرًا — خرج عن ذلك."}]}],"refs":["المغني (١/١٣)","المغني (١/١١)","بداية المجتهد (١/٣٣)","نيل الأوطار (٤/٣٩)"],"related":["الوضوء بالنبيذ وسائر المائعات","الماء المتغير بطول المكث أو بالطحلب"],"alts":["الوضوء بماء فيه صابون","الماء المخلوط","الوضوء بماء الزعفران"]},{"n":4,"bab":"الطهارة","sub":"المياه","title":"الوضوء بالماء المستعمل","q":"هل يجوز الوضوء بالماء الذي استُعمل في وضوء أو غسل قبل ذلك؟","short":"الماء المستعمل طاهر باتفاق المعتمد في المذاهب، والراجح أنه مطهِّر أيضًا ما لم يتغير؛ والأولى أن يُستعمل غيره إن تيسّر، خروجًا من الخلاف.","body":[{"t":"h","text":"صورة المسألة"},{"t":"p","text":"الماء المستعمل: هو الماء المنفصل عن أعضاء المتوضئ أو المغتسل بعد استعماله في رفع الحدث. أما ما استُعمل في التبرّد أو التنظيف فلا خلاف فيه:"},{"t":"quote","text":"وَلَا تَخْتَلِفُ الرِّوَايَةُ أَنَّ مَا اُسْتُعْمِلَ فِي التَّبَرُّدِ وَالتَّنْظِيفِ، أَنَّهُ بَاقٍ عَلَى إطْلَاقِهِ، وَلَا نَعْلَمُ فِيهِ خِلَافًا","src":"المغني","loc":"١/١٨","pre":"قال ابن قدامة:"},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"أنه طاهر غير مطهِّر، وهو ظاهر مذهب أحمد والشافعي، والمشهور عن أبي حنيفة، وإحدى الروايتين عن مالك."},{"t":"quote","text":"وَظَاهِرُ الْمَذْهَبِ أَنَّ الْمُسْتَعْمَلَ فِي رَفْعِ الْحَدَثِ طَاهِرٌ غَيْرُ مُطَهِّرٍ، لَا يَرْفَعُ حَدَثًا، وَلَا يُزِيلُ نَجَسًا، وَبِهِ قَالَ اللَّيْثُ وَالْأَوْزَاعِيُّ، وَهُوَ الْمَشْهُورُ عَنْ أَبِي حَنِيفَةَ، وَإِحْدَى الرِّوَايَتَيْنِ عَنْ مَالِكٍ، وَظَاهِرُ مَذْهَبِ الشَّافِعِيِّ","src":"المغني","loc":"١/١٦","pre":"قال ابن قدامة:"},{"t":"quote","text":"فَالدَّلِيلُ عَلَى خُرُوجِهِ عَنْ الطَّهُورِيَّةِ قَوْلُ النَّبِيِّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -: «لَا يَغْتَسِلْ أَحَدُكُمْ فِي الْمَاءِ الدَّائِمِ وَهُوَ جُنُبٌ» رَوَاهُ مُسْلِمٌ، مَنَعَ مِنْ الْغُسْلِ فِيهِ كَمَنْعِهِ مِنْ الْبَوْلِ فِيهِ، فَلَوْلَا أَنَّهُ يُفِيدُهُ مَنْعًا لَمْ يَنْهَ عَنْهُ؛ وَلِأَنَّهُ أُزِيلَ بِهِ مَانِعٌ مِنْ الصَّلَاةِ، فَلَمْ يَجُزْ اسْتِعْمَالُهُ فِي طَهَارَةٍ أُخْرَى، كَالْمُسْتَعْمَلِ فِي إزَالَةِ النَّجَاسَةِ","src":"المغني","loc":"١/١٧","pre":"ودليلهم:"},{"t":"qawl","label":"القول الثاني","text":"أنه طاهر مطهِّر، وهو رواية عن أحمد ومالك، وقول للشافعي، وقول أهل الظاهر وجماعة من التابعين."},{"t":"quote","text":"وَعَنْ أَحْمَدَ رِوَايَةٌ أُخْرَى، أَنَّهُ طَاهِرٌ مُطَهِّرٌ. وَبِهِ قَالَ الْحَسَنُ، وَعَطَاءٌ، وَالنَّخَعِيُّ، وَالزُّهْرِيُّ، وَمَكْحُولٌ، وَأَهْلُ الظَّاهِرِ، وَالرِّوَايَةُ الثَّانِيَةُ لِمَالِكٍ، وَالْقَوْلُ الثَّانِي لِلشَّافِعِيِّ. وَرُوِيَ عَنْ عَلِيٍّ، وَابْنِ عُمَرَ، وَأَبِي أُمَامَةَ فِيمَنْ نَسِيَ مَسْحَ رَأْسِهِ، إذَا وَجَدَ بَلَلًا فِي لِحْيَتِهِ، أَجْزَأَهُ أَنْ يَمْسَحَ رَأْسَهُ بِذَلِكَ الْبَلَلِ","src":"المغني","loc":"١/١٦","pre":"قال ابن قدامة:"},{"t":"quote","text":"وَوَجْهُ ذَلِكَ أَنَّ النَّبِيَّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - قَالَ: «الْمَاءُ لَا يُجْنِبُ» ، وَقَالَ: «الْمَاءُ لَيْسَ عَلَيْهِ جَنَابَةٌ» ، وَرُوِيَ «أَنَّ النَّبِيَّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - اغْتَسَلَ مِنْ الْجَنَابَةِ، فَرَأَى لُمْعَةً لَمْ يُصِبْهَا الْمَاءُ، فَعَصَرَ شَعَرَهُ عَلَيْهَا» . رَوَاهُمَا الْإِمَامُ أَحْمَدُ، فِي \" الْمُسْنَدِ \" وَابْنُ مَاجَهْ، وَغَيْرُهُمَا وَلِأَنَّهُ غُسِلَ بِهِ مَحَلٌّ طَاهِرٌ، فَلَمْ تَزُلْ بِهِ طَهُورِيَّتُهُ، كَمَا لَوْ غُسِلَ بِهِ الثَّوْبُ؛ وَلِأَنَّهُ لَاقَى مَحَلًّا طَاهِرًا، فَلَا يَخْرُجُ عَنْ حُكْمِهِ بِتَأْدِيَةِ الْفَرْضِ بِهِ، كَالثَّوْبِ يُصَلَّى فِيهِ مِرَارًا","src":"المغني","loc":"١/١٦","pre":"ودليلهم:"},{"t":"qawl","label":"القول الثالث","text":"أنه نجس، وهو قول أبي يوسف، ورواية عن أبي حنيفة."},{"t":"quote","text":"وَقَالَ أَبُو يُوسُفَ: هُوَ نَجِسٌ. وَهُوَ رِوَايَةٌ عَنْ أَبِي حَنِيفَةَ؛ لِأَنَّ النَّبِيَّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - قَالَ: «لَا يَبُولَنَّ أَحَدُكُمْ فِي الْمَاءِ الدَّائِمِ، وَلَا يَغْتَسِلْ فِيهِ مِنْ جَنَابَةٍ.» رَوَاهُ أَبُو دَاوُد فَاقْتَضَى أَنَّ الْغُسْلَ فِيهِ، كَالْبَوْلِ فِيهِ؛ وَلِأَنَّهُ يُسَمَّى طَهَارَةً وَالطَّهَارَةُ لَا تَكُونُ إلَّا عَنْ نَجَاسَةٍ، إذْ تَطْهِيرُ الطَّاهِرِ لَا يُعْقَلُ","src":"المغني","loc":"١/١٧","pre":"قال ابن قدامة:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"أما القول بنجاسته فمردود بالأحاديث الصحيحة في تبرّك الصحابة بوضوء النبي ﷺ، وصبّه وَضوءه على جابر رضي الله عنه:"},{"t":"quote","text":"جَاءَ رَسُولُ اللَّهِ - صلى الله عليه وسلم - يَعُودُنِى، وَأَنَا مَرِيضٌ لاَ أَعْقِلُ، فَتَوَضَّأَ وَصَبَّ عَلَىَّ مِنْ وَضُوئِهِ، فَعَقَلْتُ","src":"فيض الباري","loc":"١/٣٩٥","pre":"عن جابر بن عبد الله رضي الله عنهما قال (رواه البخاري برقم ١٩٤):"},{"t":"p","text":"وقد حقّق علماء الحنفية أنفسهم أن رواية النجاسة ضعيفة، وأن المفتى به عندهم طهارته؛ قال الشيخ أنور شاه الكشميري:"},{"t":"quote","text":"قال الشيخ ابن الهُمَام وابن نُجَيم رحمهما الله تعالى: إنَّ العراقيين قاطبةً أنكروا روايةَ النجاسة عن الإِمام، وهم المُتَثَبِّتُون في نقل مذهب الإِمام عندي. وأثبَتَها ما وراء النهر من علمائنا، وهي ضعيفة جدًا، لأنِّي لا أجدُ أحدًا من السلف يُعَامِلُ الماءَ المستعمل معاملة النجاسات، إلا أنه لا شك أن المطلوب عند الشرع هو صيانةُ وضوئه عنه، كما عند الطحاوي عن أبي هريرة قال رسول الله صلى الله عليه وسلّم «لا يَغْتَسِلُ أحدكُم في الماء وهو جنب»، فقال: كيف يفعل يا أبا هريرة فقال: «يتناوله تناولًا». وكذا نَهَى الرجلَ عن فَضلِ طَهورِ المرأة. عندي يُبتنى على هذه الدقيقة كما سيجيء تقريره","src":"فيض الباري","loc":"١/٣٨٦-٣٨٧"},{"t":"quote","text":"اتَّفَقَ أَصْحَابُنَا - رَحِمَهُمُ اللَّهُ - أَنَّ الْمَاءَ الْمُسْتَعْمَلَ لَيْسَ بِطَهُورٍ حَتَّى لَا يَجُوزُ التَّوَضُّؤُ بِهِ وَاخْتَلَفُوا فِي طَهَارَتِهِ قَالَ مُحَمَّدٌ - رَحِمَهُ اللَّهُ -: هُوَ طَاهِرٌ وَهُوَ رِوَايَةٌ عَنْ أَبِي حَنِيفَةَ - رَحِمَهُ اللَّهُ - وَعَلَيْهِ الْفَتْوَى","src":"الفتاوى الهندية","loc":"١/٢٢","pre":"وفي «الفتاوى الهندية»:"},{"t":"p","text":"وبقي الخلاف بين القولين الأولين في رفع الحدث به، والأظهر أنه مطهِّر؛ لأنه ماء طاهر لاقى أعضاءً طاهرة، فلم يخرج عن اسم الماء المطلق، وقد قال النبي ﷺ: «الماء لا يجنب». وأما نهيه ﷺ الجنبَ عن الاغتسال في الماء الدائم فمحمول على صيانة الماء عن أن يُستقذر ويُفسد على غيره، كما أشار إليه الشيخ الكشميري بقوله: إن المطلوب عند الشرع صيانة الوضوء عنه."},{"t":"quote","text":"وَقَدْ ثَبَتَ أَنَّ النَّبِيَّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - كَانَ أَصْحَابُهُ يَقْتَتِلُونَ عَلَى فَضْلِ وُضُوئِهِ. وَلَا بُدَّ أَنْ يَقَعَ مِنَ الْمَاءِ الْمُسْتَعْمَلِ فِي الْإِنَاءِ الَّذِي بَقِيَ فِيهِ الْفَضْلُ. وَبِالْجُمْلَةِ فَهُوَ مَاءٌ مُطْلَقٌ ; لِأَنَّهُ فِي الْأَغْلَبِ لَيْسَ يَنْتَهِي إِلَى أَنْ يَتَغَيَّرَ أَحَدُ أَوْصَافِهِ بِدَنَسِ الْأَعْضَاءِ الَّتِي تُغْسَلُ بِهِ، فَإِنِ انْتَهَى إِلَى ذَلِكَ، فَحُكْمُهُ حُكْمُ الْمَاءِ الَّذِي تَغَيَّرَ أَحَدُ أَوْصَافِهِ بِشَيْءٍ طَاهِرٍ، وَإِنْ كَانَ هَذَا تَعَافُهُ النُّفُوسُ أَكْثَرَ، وَهَذَا لَحْظُ مَنْ كَرِهَهُ، وَأَمَّا مَنْ زَعَمَ أَنَّهُ نَجِسٌ فَلَا دَلِيلَ مَعَهُ","src":"بداية المجتهد","loc":"١/٣٤","pre":"وقال ابن رشد:"}],"refs":["المغني (١/١٨)","المغني (١/١٦)","المغني (١/١٧)","فيض الباري (١/٣٩٥)","فيض الباري (١/٣٨٦-٣٨٧)","الفتاوى الهندية (١/٢٢)","بداية المجتهد (١/٣٤)"],"related":["الماء الذي خالطه شيء طاهر فغيّره"],"alts":["الماء المتساقط من الوضوء","إعادة استعمال ماء الوضوء","ماء الغسل المستعمل"]},{"n":5,"bab":"الطهارة","sub":"المياه","title":"الماء القليل تقع فيه نجاسة ولم يتغير","q":"وقعت نجاسة يسيرة في ماء قليل ولم يتغير لونه ولا طعمه ولا ريحه، فهل ينجس؟","short":"اختلف العلماء فيه على قولين مشهورين: فمنهم من قال: لا ينجس الماء إلا بالتغير، قليلًا كان أو كثيرًا؛ ومنهم من فرّق بين القليل والكثير، ثم اختلف هؤلاء في حد الكثير: فقدّره الشافعي وأحمد بالقلتين، وجعله الحنفية ما يغلب على ظن المبتلى به أن النجاسة لا تصل إلى جانبه الآخر. والأظهر دليلًا أنه لا ينجس إلا بالتغير، والأحوط أن يُترك الماء القليل الذي وقعت فيه نجاسة إذا وُجد غيره.","body":[{"t":"h","text":"تحرير محل النزاع"},{"t":"quote","text":"فَأَمَّا نَجَاسَةُ مَا تَغَيَّرَ بِالنَّجَاسَةِ فَلَا خِلَافَ فِيهِ، قَالَ ابْنُ الْمُنْذِرِ: أَجْمَعَ أَهْلُ الْعِلْمِ عَلَى أَنَّ الْمَاءَ الْقَلِيلَ وَالْكَثِيرَ، إذَا وَقَعَتْ فِيهِ نَجَاسَةٌ فَغَيَّرَتْ لِلْمَاءِ طَعْمًا أَوْ لَوْنًا أَوْ رَائِحَةً، أَنَّهُ نَجِسٌ مَا دَامَ كَذَلِكَ","src":"المغني","loc":"١/٢٠","pre":"اتفق العلماء على أن الماء إذا غيّرته النجاسة نجس، قليلًا كان أو كثيرًا؛ قال ابن قدامة:"},{"t":"p","text":"واختلفوا في الماء تقع فيه النجاسة فلا تغيّره، على قولين؛ وأصحاب القول الثاني طائفتان:"},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"أن الماء لا ينجس إلا إذا تغيّر أحد أوصافه بالنجاسة، قليلًا كان أو كثيرًا."},{"t":"quote","text":"وَرُوِيَ عَنْ أَحْمَدَ رِوَايَةٌ أُخْرَى، أَنَّ الْمَاءَ لَا يَنْجُسُ إلَّا بِالتَّغَيُّرِ قَلِيلُهُ وَكَثِيرُهُ، وَرُوِيَ مِثْلُ ذَلِكَ عَنْ حُذَيْفَةَ، وَأَبِي هُرَيْرَةَ، وَابْنِ عَبَّاسٍ، قَالُوا: الْمَاءُ لَا يَنْجُسُ. وَرُوِيَ ذَلِكَ عَنْ سَعِيدِ بْنِ الْمُسَيِّبِ، وَالْحَسَنِ، وَعِكْرِمَةَ، وَعَطَاءٍ، وَجَابِرِ بْنِ زَيْدٍ، وَابْنِ أَبِي لَيْلَى، وَمَالِكٍ وَالْأَوْزَاعِيِّ، وَالثَّوْرِيِّ، وَيَحْيَى الْقَطَّانِ، وَعَبْدِ الرَّحْمَنِ بْنِ مَهْدِيٍّ، وَابْنِ الْمُنْذِرِ، وَهُوَ قَوْلٌ لِلشَّافِعِيِّ","src":"المغني","loc":"١/٢٠","pre":"قال ابن قدامة:"},{"t":"quote","text":"فَقَالَ قَوْمٌ: هُوَ طَاهِرٌ سَوَاءٌ أَكَانَ كَثِيرًا أَوْ قَلِيلًا، وَهِيَ إِحْدَى الرِّوَايَاتِ عَنْ مَالِكٍ، وَبِهِ قَالَ أَهْلُ الظَّاهِرِ","src":"بداية المجتهد","loc":"١/٣٠","pre":"وقال ابن رشد:"},{"t":"quote","text":"عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ - رَضِيَ اللَّهُ عَنْهُ - قَالَ قَالَ رَسُولُ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - «إنَّ الْمَاءَ طَهُورٌ لَا يُنَجِّسُهُ شَيْءٌ» أَخْرَجَهُ الثَّلَاثَةُ وَصَحَّحَهُ أَحْمَدُ","src":"سبل السلام","loc":"١/٢١","pre":"ومن أدلتهم:"},{"t":"quote","text":"وَرُوِيَ أَنَّ النَّبِيَّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - «سُئِلَ عَنْ الْحِيَاضِ الَّتِي بَيْنَ مَكَّةَ وَالْمَدِينَةِ، تَرِدُهَا السِّبَاعُ وَالْكِلَابُ وَالْحُمُرُ، وَعَنْ الطَّهَارَةِ بِهَا، فَقَالَ: لَهَا مَا حَمَلَتْ فِي بُطُونِهَا، وَلَنَا مَا غَبَرَ طَهُورٌ» وَلَمْ يُفَرِّقْ بَيْنَ الْقَلِيلِ وَالْكَثِيرِ؛ وَلِأَنَّهُ لَمْ يَظْهَرْ عَلَيْهِ إحْدَى صِفَاتُ النَّجَاسَةِ، فَلَمْ يَنْجُسْ بِهَا كَالزَّائِدِ عَنْ الْقُلَّتَيْنِ","src":"المغني","loc":"١/٢٠"},{"t":"qawl","label":"القول الثاني","text":"التفريق بين القليل والكثير: فالكثير لا ينجس إلا بالتغير، والقليل ينجس بمجرد ملاقاة النجاسة وإن لم يتغير."},{"t":"quote","text":"وَقَالَ قَوْمٌ بِالْفَرْقِ بَيْنَ الْقَلِيلِ وَالْكَثِيرِ، فَقَالُوا: إِنْ كَانَ قَلِيلًا كَانَ نَجِسًا، وَإِنْ كَانَ كَثِيرًا لَمْ يَكُنْ نَجِسًا. وَهَؤُلَاءِ اخْتَلَفُوا فِي الْحَدِّ بَيْنَ الْقَلِيلِ وَالْكَثِيرِ، فَذَهَبَ أَبُو حَنِيفَةَ إِلَى أَنَّ الْحَدَّ فِي هَذَا هُوَ أَنْ يَكُونَ الْمَاءُ مِنَ الْكَثْرَةِ بِحَيْثُ إِذَا حَرَّكَهُ آدَمِيٌّ مِنْ أَحَدِ طَرَفَيْهِ لَمْ تَسْرِ الْحَرَكَةُ إِلَى الطَّرَفِ الثَّانِي مِنْهُ. وَذَهَبَ الشَّافِعِيُّ إِلَى أَنَّ الْحَدَّ فِي ذَلِكَ هُوَ قُلَّتَانِ مِنْ قلال هَجَرَ، وَذَلِكَ نَحْوُ خَمْسِمِائَةِ رِطْلٍ","src":"بداية المجتهد","loc":"١/٣٠","pre":"قال ابن رشد:"},{"t":"taifa","label":"الطائفة الأولى","text":"قدّرت الكثير بالقلتين، فما بلغهما لم ينجس إلا بالتغير، وما دونهما قليل ينجس بالملاقاة؛ وهو مذهب الشافعي، والمشهور عن أحمد، وقول إسحاق وأبي عبيد، ومروي عن ابن عمر رضي الله عنهما."},{"t":"quote","text":"وَأَمَّا مَا دُونَ الْقُلَّتَيْنِ إذَا لَاقَتْهُ النَّجَاسَةُ فَلَمْ يَتَغَيَّرْ بِهَا، فَالْمَشْهُورُ فِي الْمَذْهَبِ أَنَّهُ يَنْجُسُ، وَرُوِيَ عَنْ ابْنِ عُمَرَ، وَسَعِيدِ بْنِ جُبَيْرٍ، وَمُجَاهِدٍ، وَبِهِ قَالَ الشَّافِعِيُّ، وَإِسْحَاقُ، وَأَبُو عُبَيْدٍ","src":"المغني","loc":"١/٢٠","pre":"قال ابن قدامة:"},{"t":"quote","text":"وَعَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ - رَضِيَ اللَّهُ عَنْهُمَا - قَالَ: قَالَ رَسُولُ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -: «إذَا كَانَ الْمَاءُ قُلَّتَيْنِ لَمْ يَحْمِلْ الْخَبَثَ» وَفِي لَفْظٍ \" لَمْ يَنْجُسْ \" أَخْرَجَهُ الْأَرْبَعَةُ، وَصَحَّحَهُ ابْنُ خُزَيْمَةَ وَالْحَاكِمُ وَابْنُ حِبَّانَ","src":"سبل السلام","loc":"١/٢٥","pre":"ودليلهم:"},{"t":"quote","text":"وَتَحْدِيدُهُ بِالْقُلَّتَيْنِ يَدُلُّ عَلَى أَنَّ مَا دُونَهُمَا يَنْجُسُ، إذْ لَوْ اسْتَوَى حُكْمُ الْقُلَّتَيْنِ وَمَا دُونَهُمَا لَمْ يَكُنْ التَّحْدِيدُ مُفِيدًا","src":"المغني","loc":"١/٢١","pre":"ووجه الاستدلال كما قال ابن قدامة:"},{"t":"quote","text":"وَالْمُرَادُ بِهَا هَاهُنَا قُلَّتَانِ مِنْ قِلَالِ هَجَرَ، وَهُمَا خَمْسُ قِرَبٍ، كُلُّ قِرْبَةٍ مِائَةُ رِطْلٍ بِالْعِرَاقِيِّ، فَتَكُونُ الْقُلَّتَانِ خَمْسَمِائَةِ رِطْلٍ بِالْعِرَاقِيِّ","src":"المغني","loc":"١/١٩","pre":"وفي مقدار القلتين قال:"},{"t":"taifa","label":"الطائفة الثانية","text":"الحنفية: لم يحدّوا الكثير بعدد، بل جعلوه ما يغلب على الظن أن النجاسة لا تصل إلى جانبه الآخر، وعبّر عنه بعضهم بأنه الماء الذي إذا حُرّك أحد طرفيه لم يتحرك الآخر، وقدّره بعض متأخريهم بعشرة أذرع في عشرة."},{"t":"quote","text":"وَذَهَبَ أَبُو حَنِيفَةَ وَأَصْحَابُهُ إلَى أَنَّ الْكَثِيرَ يَنْجُسُ بِالنَّجَاسَةِ، إلَّا أَنْ يَبْلُغَ حَدًّا يَغْلِبُ عَلَى الظَّنِّ أَنَّ النَّجَاسَةَ لَا تَصِلُ إلَيْهِ. وَاخْتَلَفُوا فِي حَدِّهِ؛ فَقَالَ بَعْضُهُمْ: مَا إذَا حُرِّكَ أَحَدُ طَرَفَيْهِ لَمْ يَتَحَرَّكْ الْآخَرُ. وَقَالَ بَعْضُهُمْ: مَا بَلَغَ عَشَرَةَ أَذْرُعٍ فِي عَشَرَةِ أَذْرُعٍ، وَمَا دُونَ ذَلِكَ يَنْجُسُ، وَإِنْ بَلَغَ أَلْفَ قُلَّةٍ؛ لِأَنَّ النَّبِيَّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - قَالَ: «لَا يَبُولَنَّ أَحَدُكُمْ فِي الْمَاءِ الدَّائِمِ ثُمَّ يَتَوَضَّأُ مِنْهُ» . مُتَّفَقٌ عَلَيْهِ، فَنَهَى عَنْ الْوُضُوءِ مِنْ الْمَاءِ الرَّاكِدِ بَعْدَ الْبَوْلِ فِيهِ، وَلَمْ يُفَرِّقْ بَيْنَ قَلِيلِهِ وَكَثِيرِهِ؛ وَلِأَنَّهُ مَاءٌ حَلَّتْ فِيهِ نَجَاسَةٌ لَا يُؤْمَنُ انْتِشَارُهَا إلَيْهِ، فَيَنْجُسُ بِهَا كَالْيَسِيرِ","src":"المغني","loc":"١/٢١","pre":"قال ابن قدامة:"},{"t":"quote","text":"ففي الدر المختار: والمعتبر في مقدار الراكد أكبر رأي المبتلي به فيه فإن غلب على ظنه عدم وصول النجاسة إلى الجانب الآخر جاز وإلا لا، هذا ظاهر الرواية عن الإمام وإليه رجع محمد وهو الأصح كما في الغاية وغيرها وحقق في البحر أنه المذهب وبه يعمل","src":"الكوكب الدري على جامع الترمذي","loc":"١/٩٠","pre":"وفي بيان المعتمد عندهم قال صاحب «الكوكب الدري»:"},{"t":"p","text":"وفي المذهب المالكي روايات ثلاث في الماء اليسير تحلّه النجاسة اليسيرة:"},{"t":"quote","text":"فَيَتَحَصَّلُ عَنْ مَالِكٍ فِي الْمَاءِ الْيَسِيرِ تَحُلُّهُ النَّجَاسَةُ الْيَسِيرَةُ ثَلَاثَةُ أَقْوَالٍ: قَوْلٌ إِنَّ النَّجَاسَةَ تُفْسِدُهُ، وَقَوْلٌ إِنَّهَا لَا تُفْسِدُهُ إِلَّا أَنْ يَتَغَيَّرَ أَحَدُ أَوْصَافِهِ، وَقَوْلٌ إِنَّهُ مَكْرُوهٌ","src":"بداية المجتهد","loc":"١/٣٠","pre":"قال ابن رشد:"},{"t":"h","text":"سبب الخلاف"},{"t":"quote","text":"وَسَبَبُ اخْتِلَافِهِمْ فِي ذَلِكَ هُوَ تَعَارُضُ ظَوَاهِرِ الْأَحَادِيثِ الْوَارِدَةِ فِي ذَلِكَ، وَذَلِكَ أَنَّ حَدِيثَ أَبِي هُرَيْرَةَ الْمُتَقَدِّمَ وَهُوَ قَوْلُهُ - عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ - «إِذَا اسْتَيْقَظَ أَحَدُكُمْ مِنْ نَوْمِهِ» الْحَدِيثَ، يُفْهَمُ مِنْ ظَاهِرِهِ أَنَّ قَلِيلَ النَّجَاسَةِ يُنَجِّسُ قَلِيلَ الْمَاءِ، وَكَذَلِكَ أَيْضًا حَدِيثُ أَبِي هُرَيْرَةَ الثَّابِتُ عَنْهُ - عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ - أَنَّهُ قَالَ: «لَا يَبُولَنَّ أَحَدُكُمْ فِي الْمَاءِ الدَّائِمِ، ثُمَّ يَغْتَسِلُ فِيهِ» فَإِنَّهُ يُوهِمُ بِظَاهِرِهِ أَيْضًا أَنَّ قَلِيلَ النَّجَاسَةِ يُنَجِّسُ قَلِيلَ الْمَاءِ. وَكَذَلِكَ لِمَا وَرَدَ مِنَ النَّهْيِ عَنِ اغْتِسَالِ الْجُنُبِ فِي الْمَاءِ الدَّائِمِ. وَأَمَّا حَدِيثُ أَنَسٍ الثَّابِتُ: «أَنَّ أَعْرَابِيًّا قَامَ إِلَى نَاحِيَةٍ مِنَ الْمَسْجِدِ فَبَالَ فِيهَا، فَصَاحَ بِهِ النَّاسُ، فَقَالَ رَسُولُ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -: دَعُوهُ، فَلَمَّا فَرَغَ أَمَرَ رَسُولُ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - بِذَنُوبِ مَاءٍ فَصُبَّ عَلَى بَوْلِهِ» فَظَاهِرُهُ أَنَّ قَلِيلَ النَّجَاسَةِ لَا يُفْسِدُ قَلِيلَ الْمَاءِ، إِذْ مَعْلُومٌ أَنَّ ذَلِكَ الْمَوْضِعَ قَدْ طُهِّرَ مِنْ الذَّنُوبِ","src":"بداية المجتهد","loc":"١/٣٠-٣١","pre":"قال ابن رشد:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الذي يظهر — والله أعلم — أن الماء لا ينجس إلا بالتغير؛ لأن حديث «إن الماء طهور لا ينجسه شيء» عام، وحديث القلتين — وهو حديث صحيح — منطوقه أن ما بلغ القلتين لا يحمل الخبث، وأما مفهومه فيدل على أن ما دونهما قد يتأثر بالنجاسة فيحتاج إلى نظر، لا أنه ينجس بكل حال."},{"t":"quote","text":"وَأَمَّا تَخْصِيصُ الْقُلَّتَيْنِ بِالذِّكْرِ فَإِنَّهُمْ سَأَلُوهُ عَنْ الْمَاءِ يَكُونُ بِأَرْضِ الْفَلَاةِ؛ وَمَا يَنُوبُهُ مِنْ السِّبَاعِ وَالدَّوَابِّ؛ وَذَلِكَ الْمَاءُ الْكَثِيرُ فِي الْعَادَةِ فَبَيَّنَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّ مِثْلَ ذَلِكَ لَا يَكُونُ فِيهِ خَبَثٌ فِي الْعَادَةِ بِخِلَافِ الْقَلِيلِ فَإِنَّهُ قَدْ يَحْمِلُ الْخَبَثَ وَقَدْ لَا يَحْمِلُهُ؛ فَإِنَّ الْكَثِيرَةَ تُعِينُ عَلَى إحَالَةِ الْخَبَثِ إلَى طَبْعِهِ؛ وَالْمَفْهُومُ لَا يَجِبُ فِيهِ الْعُمُومُ فَلَيْسَ إذَا كَانَ الْقُلَّتَانِ لَا تَحْمِلُ الْخَبَثَ يَلْزَمُ أَنَّ مَا دُونَهَا يَلْزَمُهُ مُطْلَقًا عَلَى أَنَّ التَّخْصِيصَ وَقَعَ جَوَابًا لِأُنَاسِ سَأَلُوهُ عَنْ مِيَاهٍ مُعَيَّنَةٍ؛ فَقَدْ يَكُونُ التَّخْصِيصُ لِأَنَّ هَذِهِ كَثِيرَةٌ لَا تَحْمِلُ الْخَبَثَ وَالْقُلَّتَانِ كَثِيرٌ وَلَا يَلْزَمُ أَنْ لَا يَكُونَ الْكَثِيرُ إلَّا قُلَّتَيْنِ","src":"مجموع الفتاوى","loc":"٢٠/٥٢٠","pre":"قال شيخ الإسلام ابن تيمية:"},{"t":"quote","text":"قَالَ أَبُو دَاوُد: قَدَّرْت بِئْرَ بُضَاعَةَ بِرِدَائِي، مَدَدْته عَلَيْهَا، ثُمَّ ذَرَعْته، فَإِذَا عَرْضُهَا سِتَّةُ أَذْرُعٍ، وَسَأَلْت الَّذِي فَتَحَ لِي بَابَ الْبُسْتَانِ: هَلْ غُيِّرَ بِنَاؤُهَا عَمَّا كَانَتْ عَلَيْهِ؟ قَالَ: لَا. وَسَأَلْت قَيِّمَهَا عَنْ عُمْقِهَا، فَقُلْت: أَكْثَرُ مَا يَكُونُ فِيهَا الْمَاءُ؟ قَالَ: إلَى الْعَانَةِ. قُلْت: فَإِذَا نَقَصَ. قَالَ: دُونَ الْعَوْرَةِ","src":"المغني","loc":"١/٢١","pre":"ومما يدل على أن الحكم لا يتوقف على عشر في عشر: أن بئر بضاعة — وقد قال فيها النبي ﷺ: «إن الماء طهور لا ينجسه شيء» — كانت دون ذلك؛ قال ابن قدامة:"},{"t":"p","text":"وقد نبّه المحققون من علماء الحنفية أنفسهم إلى أن التقدير بعشر في عشر ليس منقولًا عن أئمة المذهب، وأن أصل المذهب الرجوع إلى غلبة الظن؛ قال الشيخ أنور شاه الكشميري:"},{"t":"quote","text":"وقال أبو حنيفة: يحكم بالنجاسة إلى حد يظن خلوص النجاسة إليه، ثم مالك اعتبر الحس، وأبو حنيفة اعتبر العلم، والظاهر أن في أكثر الأنجاس عبرة العلم، وأما ما في كتبنا من العشر في العشر فعين توقيت وهو ليس بمروي عن أئمتنا الثلاثة، وقال الشيخ في الفتح: إن محمداً ليس بمؤقت، ولو سُلِّم فرجع عنه، وحكى أن محمداً سئل عن الماء الكثير فقال: نحو مسجدي هذا، فقدره تلامذته فوجدوه ثمانية في ثمانية من داخله، وعشراً في عشر من خارجه، وفي الفتح عن محمد: لا أوقت فيه، ونقل صاحب البحر عبارات أركان المذاهب على أن العشر في العشر ليس عن الأئمة، وأما ما في القدوري من تحرك الطرف بتحريك طرف آخر فهو علامة العلم بالخلوص، وأول من قال في العشر أبو سليمان الجوجزاني كما في الفتاوى الهندية","src":"العرف الشذي","loc":"١/٩٧"},{"t":"p","text":"وأثبت الشاه ولي الله الدهلوي صحة حديث القلتين، وبيّن أن ما أطالوا فيه من فروع نزح الآبار لا يقوم عليه دليل يُعتدّ به:"},{"t":"quote","text":"حَدِيث الْقلَّتَيْنِ فَإِنَّهُ حَدِيث صَحِيح روى بطرق كَثِيرَة معظمها ترجع إِلَى أبي الْوَلِيد بن كثير. عَن مُحَمَّد بن جَعْفَر بن الزبير عَن عبد الله - أَو مُحَمَّد بن عباد بن جَعْفَر - عَن عبيد الله بن عبد الله كِلَاهُمَا عَن ابْن عمر، ثمَّ تشعبت الطّرق بعد ذَلِك؛ وَهَذَانِ وَإِن كَانَا من الثِّقَات لكنهما لَيْسَ مِمَّن وسد إِلَيْهِم الْفَتْوَى، وعول النَّاس عَلَيْهِم، فَلم يظْهر الحَدِيث فِي عصر سعيد بن الْمسيب وَلَا فِي عصر الزُّهْرِيّ، وَلم يمش عَلَيْهِ الْمَالِكِيَّة وَلَا الْحَنَفِيَّة، فَلم يعملوا بِهِ، وَعمل بِهِ الشَّافِعِي","src":"حجة الله البالغة","loc":"١/٢٥٣"},{"t":"quote","text":"وَقد أَطَالَ الْقَوْم من فروع موت الْحَيَوَان فِي الْبِئْر، وَالْعشر فِي الْعشْر، وَالْمَاء الْجَارِي وَلَيْسَ فِي كل ذَلِك حَدِيث عَن النَّبِي صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ألبته، وَأما الْآثَار المنقولة عَن الصَّحَابَة وَالتَّابِعِينَ كأثر ابْن الزبير فِي الزنْجِي، وَعلي رَضِي الله عَنهُ فِي الْفَأْرَة، وَالنَّخَعِيّ. وَالشعْبِيّ فِي نَحْو السنور فَلَيْسَتْ مِمَّا يشْهد لَهُ المحدثون بِالصِّحَّةِ وَلَا مِمَّا اتّفق عَلَيْهِ جُمْهُور أهل الْقُرُون الأولى،، وعَلى تَقْدِير صِحَّتهَا يُمكن أَن يكون ذَلِك تطبيبا للقلوب وتنظيفا للْمَاء لَا من جِهَة الْوُجُوب الشَّرْعِيّ كَمَا ذكر فِي كتب الْمَالِكِيَّة، وَدون نفي هَذَا الِاحْتِمَال خرط القتاد. وَبِالْجُمْلَةِ فَلَيْسَ فِي هَذَا الْبَاب شَيْء يعْتد بِهِ، وَيجب الْعَمَل عَلَيْهِ، وَحَدِيث الْقلَّتَيْنِ أثبت فِي ذَلِك كُله بِغَيْر شُبْهَة، وَمن الْمحَال أَن يكون الله تَعَالَى شرع فِي هَذِه الْمسَائِل لعبادة شَيْئا زِيَادَة على مَا لَا ينفكون عَنهُ من الارتفاقات وَهِي مِمَّا يكثر وُقُوعه، وتعم بِهِ الْبلوى، ثمَّ لَا ينص عَلَيْهِ النَّبِي صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نصا جليا، وَلَا يستفيض فِي الصَّحَابَة وَمن بعدهمْ وَلَا حَدِيث وَاحِد فِيهِ","src":"حجة الله البالغة","loc":"١/٣١٣","pre":"وقال:"},{"t":"quote","text":"ويؤيِّده ما حكاه أصحاب الفتاوى المعتمدة من أصحابنا من تقليد أبي يوسف يوماً الشافعيَّ في طهارة القُلَّتَيْن، وإلى الله المشتكى من جهلة زماننا حيث يطعنون على من ترك تقليد إمامه في مسألة واحدة لقوة دليلها، ويُخرجونه عن مقلِّديه","src":"التعليق الممجد","loc":"١/٥٧","pre":"بل حكى العلامة عبد الحي اللكنوي أن الإمام أبا يوسف أخذ يومًا بقول الشافعي في القلتين، وأنكر على من يعيب ترك قول الإمام لقوة الدليل، فقال:"},{"t":"tanbih","items":[{"t":"p","text":"من وجد ماءً قليلًا وقعت فيه نجاسة لم تغيّره، وتيسّر له غيره، فالأحوط أن يتركه إلى غيره؛ خروجًا من خلاف القائلين بنجاسته، وعملًا بمفهوم حديث القلتين. فإن لم يجد غيره توضأ به، ولا يعدل إلى التيمم."}]}],"refs":["المغني (١/٢٠)","بداية المجتهد (١/٣٠)","سبل السلام (١/٢١)","سبل السلام (١/٢٥)","المغني (١/٢١)","المغني (١/١٩)","الكوكب الدري على جامع الترمذي (١/٩٠)","بداية المجتهد (١/٣٠-٣١)","مجموع الفتاوى (٢٠/٥٢٠)","العرف الشذي (١/٩٧)","حجة الله البالغة (١/٢٥٣)","حجة الله البالغة (١/٣١٣)","التعليق الممجد (١/٥٧)"],"related":["تطهير الماء النجس","تطهير البئر","مياه الصرف الصحي بعد معالجتها"],"alts":["نجاسة في ماء قليل","حديث القلتين","وقوع فأرة في الماء","عشر في عشر"]},{"n":6,"bab":"الطهارة","sub":"المياه","title":"الوضوء بالماء المسخَّن بالشمس أو بالنار","q":"هل يُكره الوضوء بالماء الذي سخّنته الشمس، أو بالماء المسخَّن بالنار والسخّانات؟","short":"لا يُكره الوضوء بالماء المسخَّن بالشمس ولا بالنار عند جمهور العلماء، واختاره النووي من الشافعية، والحديث الوارد في النهي عن المشمَّس لا يثبت؛ إلا إذا كان شديد الحرارة يمنع إسباغ الوضوء أو يضرّ.","body":[{"t":"h","text":"صورة المسألة"},{"t":"p","text":"المسألة فرعان: الماء المسخَّن بالنار — ومنه ماء السخّانات اليوم — والماء المشمَّس، وهو الذي سخّنته الشمس، ولا سيما إذا قُصد تشميسه في الأواني."},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"لا يُكره الوضوء بالمسخَّن بالنار ولا بالمشمَّس، وهو مذهب مالك وأبي حنيفة وأحمد وداود والجمهور."},{"t":"quote","text":"وَلَا يُكْرَهُ الْوُضُوءُ بِالْمَاءِ الْمُسَخَّنِ بِطَاهِرٍ، إلَّا أَنْ يَكُونَ حَارًّا يَمْنَعُ إسْبَاغَ الْوُضُوءِ لِحَرَارَتِهِ. وَمِمَّنْ رُوِيَ عَنْهُ أَنَّهُ رَأَى الْوُضُوءَ بِالْمَاءِ الْمُسَخَّنِ عُمَرُ وَابْنُهُ، وَابْنُ عَبَّاسٍ، وَأَنَسٌ - رَضِيَ اللَّهُ عَنْهُمْ -. وَهُوَ قَوْلُ أَهْلِ الْحِجَازِ وَأَهْلِ الْعِرَاقِ جَمِيعِهِمْ غَيْرَ مُجَاهِدٍ","src":"المغني","loc":"١/١٤","pre":"قال ابن قدامة في المسخن بالنار:"},{"t":"quote","text":"وَمَذْهَبُ مَالِكٍ وَأَبِي حَنِيفَةَ وَأَحْمَدَ وَدَاوُد وَالْجُمْهُورِ أَنَّهُ لَا كَرَاهَةَ كَمَا هُوَ الْمُخْتَارُ","src":"المجموع","loc":"١/٨٨","pre":"وقال النووي في المشمس:"},{"t":"qawl","label":"القول الثاني","text":"كراهة الوضوء بالماء المشمَّس إذا قُصد تشميسه، وهو المشهور عند كثير من أصحاب الشافعي، واختاره أبو الحسن التميمي من الحنابلة؛ وكره مجاهدٌ المسخَّنَ بالنار."},{"t":"quote","text":"وَقَالَ الشَّافِعِيُّ: تُكْرَهُ الطَّهَارَةُ بِمَاءٍ قُصِدَ إلَى تَشْمِيسِهِ فِي الْأَوَانِي، وَلَا أَكْرَهُهُ إلَّا مِنْ جِهَةِ الطِّبِّ؛ لِمَا رُوِيَ عَنْ عَائِشَةَ - رَضِيَ اللَّهُ عَنْهَا - قَالَتْ: «دَخَلَ عَلَيَّ رَسُولُ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - وَقَدْ سَخَّنْت لَهُ الْمَاءَ فِي الشَّمْسِ، فَقَالَ: لَا تَفْعَلِي يَا حُمَيْرَاءُ، فَإِنَّهُ يُورِثُ الْبَرَصَ» وَاخْتَارَهُ أَبُو الْحَسَنِ التَّمِيمِيُّ","src":"المغني","loc":"١/١٤-١٥","pre":"قال ابن قدامة:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الراجح القول الأول؛ لأن حديث «يورث البرص» لا يثبت، والتسخين صفة لا تُخرج الماء عن إطلاقه."},{"t":"quote","text":"وَلَنَا أَنَّهُ سُخِّنَ بِطَاهِرٍ، أَشْبَهَ مَا فِي الْبِرَكِ وَالْأَنْهَارِ، وَمَا سُخِّنَ بِالنَّارِ وَمَا لَمْ يُقْصَدْ تَشْمِيسُهُ، فَإِنَّ الضَّرَرَ لَا يَخْتَلِفُ بِالْقَصْدِ وَعَدَمِهِ، وَالْحَدِيثُ غَيْرُ ثَابِتٍ، يَرْوِيهِ، خَالِدُ بْنُ إسْمَاعِيلَ، وَهُوَ مَتْرُوكُ الْحَدِيثِ، وَعَمْرُو بْنُ مُحَمَّدٍ الْأَعْسَمُ، وَهُوَ مُنْكَرُ الْحَدِيثِ. قَالَهُ الدَّارَقُطْنِيّ، قَالَ: وَلَا يَصِحُّ عَنْ الزُّهْرِيِّ. وَحُكِيَ عَنْ أَهْلِ الطِّبِّ أَنَّهُمْ لَا يَعْرِفُونَ لِذَلِكَ تَأْثِيرًا فِي الضَّرَرِ","src":"المغني","loc":"١/١٥","pre":"قال ابن قدامة:"},{"t":"quote","text":"لَا أَكْرَهُ الْمُشَمَّسَ إلَّا أَنْ يُكْرَهَ مِنْ جِهَةِ الطِّبِّ كَذَا رَأَيْتُهُ فِي الْأُمِّ: وَكَذَا نَقَلَهُ الْبَيْهَقِيُّ بِإِسْنَادِهِ فِي كِتَابِهِ مَعْرِفَةُ السُّنَنِ وَالْآثَارِ عَنْ الشَّافِعِيِّ: وَأَمَّا قَوْلُهُ فِي مُخْتَصَرِ الْمُزَنِيِّ إلَّا مِنْ جِهَةِ الطِّبِّ لِكَرَاهَةِ عُمَرَ لِذَلِكَ وَقَوْلِهِ إنَّهُ يُورِثُ الْبَرَصَ فَلَيْسَ صَرِيحًا فِي مُخَالَفَةِ نَصِّهِ فِي الام بل يمكن جمله عَلَيْهِ فَيَكُونُ مَعْنَاهُ لَا أَكْرَهُهُ إلَّا مِنْ جهة الطلب إنْ قَالَ أَهْلُ الطِّبِّ إنَّهُ يُورِثُ الْبَرَصَ","src":"المجموع","loc":"١/٨٧-٨٨","pre":"وحقّق النووي أن نص الإمام الشافعي نفسه في «الأم» على عدم الكراهة إلا من جهة الطب، فقال:"},{"t":"tanbih","items":[{"t":"p","text":"إذا كان الماء شديد الحرارة أو البرودة بحيث يمنع إسباغ الوضوء أو يضرّ بالبدن، تُرك لضرره، لا لأنه غير طهور."}]}],"refs":["المغني (١/١٤)","المجموع (١/٨٨)","المغني (١/١٤-١٥)","المغني (١/١٥)","المجموع (١/٨٧-٨٨)"],"related":["الإسراف في ماء الوضوء"],"alts":["ماء السخان","الماء الحار للوضوء","الماء المشمس يورث البرص"]},{"n":7,"bab":"الطهارة","sub":"المياه","title":"الوضوء بالنبيذ وسائر المائعات","q":"هل يصح الوضوء بالنبيذ أو العصير أو ماء الورد عند عدم الماء؟","short":"لا يصح الوضوء بغير الماء، فمن لم يجد ماءً تيمّم؛ وهذا قول الجمهور، وهو المفتى به عند الحنفية أيضًا في نبيذ التمر.","body":[{"t":"h","text":"تحرير محل النزاع"},{"t":"quote","text":"فَأَمَّا غَيْرُ النَّبِيذِ مِنْ الْمَائِعَاتِ، غَيْرِ الْمَاءِ، كَالْخَلِّ، وَالدُّهْنِ، وَالْمَرَقِ، وَاللَّبَنِ، فَلَا خِلَافَ بَيْنَ أَهْلِ الْعِلْمِ، فِيمَا نَعْلَمُ، أَنَّهُ لَا يَجُوزُ بِهَا وُضُوءٌ وَلَا غُسْلٌ","src":"المغني","loc":"١/١٠","pre":"اتفق العلماء على أن المائعات غير الماء — كالخل واللبن والعصير — لا يُتوضأ بها؛ قال ابن قدامة:"},{"t":"p","text":"وإنما اختُلف في نبيذ التمر خاصة إذا لم يوجد الماء."},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"لا يجوز الوضوء بالنبيذ، بل يتيمم من عدم الماء، وهو قول مالك والشافعي وأحمد وأبي يوسف، والرواية التي استقر عليها المذهب الحنفي."},{"t":"quote","text":"وَمِنْهَا اخْتِصَاصُ حُصُولِ الطَّهَارَةِ بِالْمَاءِ، لِتَخْصِيصِهِ إيَّاهُ بِالذِّكْرِ، فَلَا يَحْصُلُ بِمَائِعٍ سِوَاهُ، وَبِهَذَا قَالَ مَالِكٌ وَالشَّافِعِيُّ، وَأَبُو عُبَيْدٍ وَأَبُو يُوسُفَ","src":"المغني","loc":"١/١٠","pre":"قال ابن قدامة:"},{"t":"aya","text":"فَلَمْ تَجِدُوا۟ مَآءً فَتَيَمَّمُوا۟ صَعِيدًا طَيِّبًا","ref":"المائدة: ٦"},{"t":"quote","text":"وَهَذَا نَصٌّ فِي الِانْتِقَالِ إلَى التُّرَابِ عِنْدَ عَدَمِ الْمَاءِ، وَقَالَ النَّبِيُّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -: «الصَّعِيدُ الطَّيِّبُ وَضُوءُ الْمُسْلِمِ وَإِنْ لَمْ يَجِدْ الْمَاءَ عَشْرَ سِنِينَ","src":"المغني","loc":"١/١٠","pre":"قال ابن قدامة:"},{"t":"qawl","label":"القول الثاني","text":"جواز الوضوء بنبيذ التمر عند عدم الماء، أو الجمع بينه وبين التيمم، وهو مروي عن عكرمة والحسن والأوزاعي وإسحاق، وعن أبي حنيفة روايات."},{"t":"quote","text":"وَرُوِيَ عَنْ عَلِيٍّ - رَضِيَ اللَّهُ عَنْهُ - وَلَيْسَ بِثَابِتٍ عَنْهُ - أَنَّهُ كَانَ لَا يَرَى بَأْسًا بِالْوُضُوءِ بِالنَّبِيذِ، وَبِهِ قَالَ الْحَسَنُ وَالْأَوْزَاعِيُّ وَقَالَ عِكْرِمَةُ النَّبِيذُ وَضُوءُ مَنْ لَمْ يَجِدُ الْمَاءَ. وَقَالَ إِسْحَاقُ: النَّبِيذُ حُلْوًا أَحَبُّ إلَيَّ مِنْ التَّيَمُّمِ، وَجَمْعُهُمَا أَحَبُّ إلَيَّ","src":"المغني","loc":"١/١٠","pre":"قال ابن قدامة:"},{"t":"quote","text":"وعن أبي حنيفة روايات: في رواية: الجمع بين الوضوء والتيمم، وأيهما قدم جاز، وفي رواية: يتوضأ ولا يتيمم، وفي رواية العكس، والثالثة جزم بها قاضي خان، واعتمد عليها صاحب البحر، واختارها الطحاوي، وربما ينقل رجوع الإمام إليها فلم يبق المحل لأن يطنب فيه ويبحث","src":"العرف الشذي","loc":"١/١٢١","pre":"وقال الشيخ أنور شاه الكشميري في بيان الروايات عن أبي حنيفة:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الراجح القول الأول؛ لأن القرآن نقل من الماء إلى التيمم بلا واسطة، وحديث ليلة الجن الذي احتُجّ به للوضوء بالنبيذ لا يثبت."},{"t":"quote","text":"وَحَدِيثُهُمْ لَا يَثْبُتُ، وَرَاوِيهِ أَبُو زَيْدٍ مَجْهُولٌ عِنْدَ أَهْلِ الْحَدِيثِ، لَا يُعْرَفُ لَهُ غَيْرُ هَذَا الْحَدِيثِ، وَلَا يُعْرَفُ بِصُحْبَةِ عَبْدِ اللَّهِ. قَالَهُ التِّرْمِذِيُّ وَابْنُ الْمُنْذِرِ، وَقَدْ رُوِيَ عَنْ ابْنِ مَسْعُودٍ، أَنَّهُ سُئِلَ: هَلْ كُنْت مَعَ رَسُولِ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - لَيْلَةَ الْجِنِّ؟ فَقَالَ: مَا كَانَ مَعَهُ مِنَّا أَحَدٌ. رَوَاهُ أَبُو دَاوُد. وَرَوَى مُسْلِمٌ بِإِسْنَادِهِ، عَنْ ابْنِ مَسْعُودٍ، قَالَ: لَمْ أَكُنْ مَعَ رَسُولِ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - لَيْلَةَ الْجِنِّ، وَوَدِدْت أَنِّي كُنْت مَعَهُ","src":"المغني","loc":"١/١٠","pre":"قال ابن قدامة:"},{"t":"p","text":"وهذا ما قرّره محققو الحنفية أنفسهم؛ قال الشيخ أنور شاه الكشميري:"},{"t":"quote","text":"واتفق أئمة الحديث، على تضعيف الحديث، وأبو زيد مجهول الحال لا مجهول العين، فإنه روى عنه التلميذان أبو فزارة راشد بن كيسان وأبو روق عطية بن الحارث، فصار معلوم العين بضابطة المحدثين","src":"العرف الشذي","loc":"١/١٢١"},{"t":"quote","text":"ولم أجد أحداً من الحفاظ والمحدثين يصحح حديثاً من أحاديث الوضوء بالنبيذ","src":"العرف الشذي","loc":"١/١٢١","pre":"وقال:"},{"t":"p","text":"ثم ذكر الشيخ رحمه الله رواية أخرجها الزيلعي يرى أن سندها يقوى بعد تصحيح خطأ في أسماء بعض رواتها (العرف الشذي ١/١٢١)؛ والذي عليه أئمة الحديث تضعيف أحاديث الباب، كما نقله هو نفسه."},{"t":"quote","text":"وَيُقَدِّمُ التَّيَمُّمَ عَلَى نَبِيذِ التَّمْرِ عَلَى الْمَذْهَبِ الْمُصَحَّحِ الْمُفْتَى بِهِ","src":"الدر المختار مع رد المحتار","loc":"١/٢٢٧","pre":"وفي «الدر المختار»:"},{"t":"quote","text":"وَأما الْوضُوء من المَاء الْمُقَيد الَّذِي لَا ينْطَلق عَلَيْهِ اسْم المَاء بِلَا قيد فَأمر تَدْفَعهُ الْملَّة بادئ الرَّأْي","src":"حجة الله البالغة","loc":"١/٣١٣","pre":"وقال الشاه ولي الله الدهلوي:"}],"refs":["المغني (١/١٠)","العرف الشذي (١/١٢١)","الدر المختار مع رد المحتار (١/٢٢٧)","حجة الله البالغة (١/٣١٣)"],"related":["الماء الذي خالطه شيء طاهر فغيّره","متى يجوز التيمم"],"alts":["الوضوء بالعصير","نبيذ التمر","الوضوء بماء الورد"]},{"n":8,"bab":"الطهارة","sub":"المياه","title":"سؤر الهرة وسؤر الحيوانات","q":"شربت الهرة من ماء، فهل يجوز الوضوء منه أو شربه؟ وما حكم سؤر الحيوانات عمومًا؟","short":"سؤر الهرة طاهر، يجوز الوضوء منه وشربه، وهذا محل اتفاق في الإجزاء، وإنما كره بعضهم الوضوء به تنزيهًا؛ وسؤر الآدمي وبهيمة الأنعام طاهر بالاتفاق.","body":[{"t":"h","text":"تحرير محل النزاع"},{"t":"p","text":"السؤر: بقية الماء التي يُبقيها الشارب في الإناء."},{"t":"quote","text":"اتَّفَقَ الْعُلَمَاءُ عَلَى طَهَارَةِ أَسْآرِ الْمُسْلِمِينَ، وَبَهِيمَةِ الْأَنْعَامِ، وَاخْتَلَفُوا فِيمَا عَدَا ذَلِكَ اخْتِلَافًا كَثِيرًا، فَمِنْهُمْ مَنْ زَعَمَ أَنَّ كُلَّ حَيَوَانٍ طَاهِرُ السُّؤْرِ، وَمِنْهُمْ مَنِ اسْتَثْنَى مِنْ ذَلِكَ الْخِنْزِيرَ فَقَطْ، وَهَذَانِ الْقَوْلَانِ مَرْوِيَّانِ عَنْ مَالِكٍ، وَمِنْهُمْ مَنِ اسْتَثْنَى مِنْ ذَلِكَ الْخِنْزِيرَ وَالْكَلْبَ، وَهُوَ مَذْهَبُ الشَّافِعِيِّ وَمِنْهُمْ مَنِ اسْتَثْنَى مِنْ ذَلِكَ السِّبَاعَ عَامَّةً، وَهُوَ مَذْهَبُ ابْنِ الْقَاسِمِ، وَمِنْهُمْ مَنْ ذَهَبَ إِلَى أَنَّ الْأَسْآرَ تَابِعَةٌ لِلُّحُومِ، فَإِنْ كَانَتِ اللُّحُومُ مُحَرَّمَةً فَالْأَسْآرُ نَجِسَةٌ، وَإِنْ كَانَتْ مَكْرُوهَةً فَالْأَسْآرُ مَكْرُوهَةٌ، وَإِنْ كَانَتْ مُبَاحَةً فَالْأَسْآرُ طَاهِرَةٌ","src":"بداية المجتهد","loc":"١/٣٤","pre":"قال ابن رشد في أقوال العلماء في أسآر الحيوان عامة:"},{"t":"h","text":"أقوال العلماء في سؤر الهرة"},{"t":"qawl","label":"القول الأول","text":"أنه طاهر يُتوضأ به بلا كراهة، وهو قول جمهور العلماء."},{"t":"quote","text":"وَعَنْ أَبِي قَتَادَةَ - رَضِيَ اللَّهُ عَنْهُ -، «أَنَّ رَسُولَ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - قَالَ - فِي الْهِرَّةِ -: إنَّهَا لَيْسَتْ بِنَجَسٍ، إنَّمَا هِيَ مِنْ الطَّوَّافِينَ عَلَيْكُمْ» أَخْرَجَهُ الْأَرْبَعَةُ، وَصَحَّحَهُ التِّرْمِذِيُّ وَابْنُ خُزَيْمَةَ","src":"سبل السلام","loc":"١/٣٢","pre":"ودليلهم:"},{"t":"qawl","label":"القول الثاني","text":"أنه طاهر يجزئ الوضوء به، ويُكره تنزيهًا مع وجود غيره، وهو قول أبي حنيفة ومحمد؛ وكان ابن عمر رضي الله عنهما لا يتوضأ بفضل الهر."},{"t":"quote","text":"ظاهر كلامه أن الكراهة في سؤر الهرة تنزيهية، وهو ظاهر كلامه في \"كتاب الآثار\"، حيث روى عن أبي حنيفة، عن حماد، عن إبراهيم في السِّنَّوْر يشرب في الإِناء، قال: هي من أهل البيت، لا بأس بشرب فضلها، فسألته أيُتطهَّر بفضلها للصلاة؟ فقال: إن الله قد رخَّص الماء. ولم يأمره ولم ينهه، ثم قال: قال أبو حنيفة: غيره أحبُّ إليَّ منه، وإن توضأ به أجزاه وإن شربه فلا بأس به، وبقول أبي حنيفة نأخذ","src":"التعليق الممجد","loc":"١/٣٥٠","pre":"قال العلامة عبد الحي اللكنوي في شرح قول الإمام محمد في موطئه:"},{"t":"quote","text":"قد صرح محمد في الموطأ وكتاب الآثار والمبسوط بالكراهة تنزيهاً وهو المشهور في الكتب، ثم الكراهة إما لنجاسة لحمها، وإما لعدم توقيهما من النجاسات، واختار ابن الهمام الثاني","src":"العرف الشذي","loc":"١/١٢٥","pre":"وقال الشيخ أنور شاه الكشميري:"},{"t":"quote","text":"فقد أخرج الطحاوي في \"شرح معاني الآثار\"، عن يزيد بن سنان، نا أبو بكر الحنفي، نا عبد الله بن نافع، عن أبيه، عن ابن عمر، أنه كان لا يتوضأ بفضل الكلب والهر، وما سوى ذلك فليس به بأس. وأخرج أيضاً عن ابن أبي داود، نا الربيع بن يحيى، نا شعبة، عن واقد بن محمد، عن نافع، عن ابن عمر، أنه قال: لا توضؤوا من سؤر الحمار ولا الكلب ولا السّنَّور","src":"التعليق الممجد","loc":"١/٣٤٨","pre":"وفي الأثر عن ابن عمر قال اللكنوي:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الراجح أن سؤر الهرة طاهر لا كراهة فيه؛ لأن النبي ﷺ علّل طهارته بكثرة تطوافها على الناس، وأصغى لها الإناء. وقد نصّ الإمام أبو حنيفة نفسه على أنه يجزئ الوضوء به، فالخلاف إنما هو في الأولوية لا في الصحة."},{"t":"quote","text":"وأما التابعون ومن بعدهم فاختلفوا فيه أيضاً بعد اتفاقهم على أن سؤر الهرة ليس بنجس إلاَّ ما يُستفاد مما حكاه صاحب \"رحمة الأمة في اختلاف الأئمة\"، عن الأَوْزاعي والثوري، أن سؤر ما لا يؤكل لحمه نجس غير الآدمي، فإنه يقتضي أن يكون سؤر الهرة نجساً عندهما. والأحاديث الواردة في ذلك تردّهما، ومن عداهما بعدما اتفقوا على الطهارة، منهم: من كره سؤر الهرة، وهو قول أبي حنيفة ومحمد، وبه قال طاووس وابن سيرين وابن أبي ليلى ويحيى الأنصاري، حكاه عنهم العيني","src":"التعليق الممجد","loc":"١/٣٤٨","pre":"قال اللكنوي:"},{"t":"quote","text":"ويُستنبط من قوله صلّى الله عليه وسلّم: \"فإنها من الطوّافين\"، عدم نجاسة سؤر جميع سواكن البيوت لوجود هذه العلة فيها","src":"التعليق الممجد","loc":"١/٣٤٨","pre":"وقال:"}],"refs":["بداية المجتهد (١/٣٤)","سبل السلام (١/٣٢)","التعليق الممجد (١/٣٥٠)","العرف الشذي (١/١٢٥)","التعليق الممجد (١/٣٤٨)"],"related":["ولوغ الكلب في الإناء"],"alts":["شرب القطة من الماء","سؤر القط","بقية شراب الحيوان"]},{"n":9,"bab":"الطهارة","sub":"المياه","title":"ولوغ الكلب في الإناء","q":"شرب كلب من إناء، فكيف يُطهَّر الإناء؟ وما حكم الماء الذي ولغ فيه؟","short":"يُراق ما ولغ فيه الكلب، ويُغسل الإناء سبع مرات، أولاهن بالتراب؛ وهذا نص الحديث الصحيح، وقد صرّح علماء الحنفية باستحباب السبع، فالعمل به جامع بين النص والخروج من الخلاف.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"وَعَنْ أَبِي هُرَيْرَةَ - رَضِيَ اللَّهُ عَنْهُ - قَالَ: قَالَ رَسُولُ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - «طُهُورُ إنَاءِ أَحَدِكُمْ إذَا وَلَغَ فِيهِ الْكَلْبُ أَنْ يَغْسِلَهُ سَبْعَ مَرَّاتٍ، أُولَاهُنَّ بِالتُّرَابِ» أَخْرَجَهُ مُسْلِمٌ","src":"سبل السلام","loc":"١/٣٠"},{"t":"quote","text":"إِذَا وَلَغَ الْكَلْبُ فِي إِنَاءِ أَحَدِكُمْ فَلْيُرِقْهُ وَلْيَغْسِلْهُ سَبْعَ مَرَّاتٍ","src":"بداية المجتهد","loc":"١/٣٥","pre":"وفي لفظ لمسلم:"},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"أن سؤر الكلب نجس، ويُغسل الإناء منه سبعًا إحداهن بالتراب، وهو مذهب الشافعي وأحمد."},{"t":"quote","text":"قال الشافعي وأحمد: إن الإناء الذي ولغ فيه الكلب يغسل سبع مرات، وفي رواية عن أحمد ثمان مرات، ويستحب التتريب عند أهل المذهبين","src":"العرف الشذي","loc":"١/١٢٤","pre":"قال الشيخ أنور شاه الكشميري في حكاية المذاهب:"},{"t":"qawl","label":"القول الثاني","text":"أن سؤر الكلب طاهر، والغسل سبعًا تعبّد غير معلَّل، وهو المشهور عن مالك."},{"t":"quote","text":"فَذَهَبَ مَالِكٌ بِالْأَمْرِ بِإِرَاقَةِ سُؤْرِ الْكَلْبِ وَغَسْلِ الْإِنَاءِ مِنْهُ، إِلَى أَنَّ ذَلِكَ عِبَادَةٌ غَيْرُ مُعَلَّلَةٍ، وَأَنَّ الْمَاءَ الَّذِي يَلِغُ فِيهِ لَيْسَ بِنَجِسٍ، وَلَمْ يَرَ إِرَاقَةَ مَا عَدَا الْمَاءَ مِنَ الْأَشْيَاءِ الَّتِي يَلِغُ فِيهَا الْكَلْبُ فِي الْمَشْهُورِ عَنْهُ","src":"بداية المجتهد","loc":"١/٣٦","pre":"قال ابن رشد:"},{"t":"qawl","label":"القول الثالث","text":"أن سؤر الكلب نجس، ويُغسل الإناء منه ثلاثًا كسائر النجاسات، وهو مذهب الحنفية، واحتجوا بفتوى أبي هريرة رضي الله عنه بالثلاث."},{"t":"quote","text":"ثم نقول بالغسل ثلاثاً، ويقول الشوافع بالغسل سبعاً، وجواب الحديث من جانبنا أن التسبيع مستحب عندنا كما صرح به فخر الدين الزيلعي الفقيه شارح الكنز، ثم وجدته مروياً عن أبي حنيفة: في تحرير ابن الهمام عن الوبري عن أبي حنيفة فإن أبا هريرة راوي الحديث أفتى بالغسل ثلاثاً كما في الطحاوي ص (13) ، عن عطاء عن أبي هريرة بسند قوي بإقرار ابن دقيق العيد، وفي فتوى أبي هريرة الآخر التسبيع، فقال الحافظ: المأخوذ من الفتوتين ما يوافق المرفوع، ونقول: لو كان الواجب التسبيع كيف اكتفى أبو هريرة بالتثليث؟ فالتثليث واجب والتسبيع مستحب","src":"العرف الشذي","loc":"١/١٢٤","pre":"قال الكشميري:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الراجح العمل بنص الحديث: الإراقة والغسل سبعًا أولاهن بالتراب. وأما القول بطهارة سؤره مع الأمر بغسله سبعًا فبعيد؛ وقد ناقشه الكشميري بقوله:"},{"t":"quote","text":"ويرد عليه أنه لو لم يكن سؤره نجساً فكيف يأمر الشارع بالغسل سبع مرات، ولم يكتف بالمرة الواحدة","src":"العرف الشذي","loc":"١/١٢٤"},{"t":"p","text":"وأما فتوى أبي هريرة رضي الله عنه بالثلاث، فقد رُوي عنه أيضًا الإفتاء بالسبع، والمأخوذ من الفتويين ما يوافق المرفوع، كما نقله الشيخ الكشميري عن الحافظ ابن حجر في كلامه السابق؛ ونقل فيه أيضًا تصريح علماء الحنفية باستحباب السبع، وأنه مرويّ عن الإمام أبي حنيفة نفسه."},{"t":"p","text":"فمن غسل سبعًا أولاهن بالتراب فقد عمل بنص الحديث، وبما استحبّه علماء الحنفية، وخرج من الخلاف كله."},{"t":"tanbih","items":[{"t":"p","text":"يقوم مقامَ التراب عند بعض أهل العلم ما يقوم مقامه في الإزالة من المنظفات، والأولى التزام التراب لورود النص به."}]}],"refs":["سبل السلام (١/٣٠)","بداية المجتهد (١/٣٥)","العرف الشذي (١/١٢٤)","بداية المجتهد (١/٣٦)"],"related":["سؤر الهرة وسؤر الحيوانات","أنواع النجاسات"],"alts":["غسل الإناء من الكلب","لعاب الكلب","التتريب"]},{"n":10,"bab":"الطهارة","sub":"المياه","title":"مياه الصرف الصحي بعد معالجتها","q":"هل يجوز الوضوء بمياه الصرف الصحي (المجاري) بعد تنقيتها في محطات المعالجة؟","short":"إذا نُقّيت تنقية كاملة حتى زال أثر النجاسة منها، فلا يظهر فيها طعمها ولا لونها ولا ريحها، فهي طاهرة مطهّرة يجوز الوضوء بها؛ والأولى الاستغناء عنها في الشرب متى وُجد غيرها.","body":[{"t":"h","text":"أصل المسألة"},{"t":"p","text":"هذه مسألة معاصرة، تُبنى على أصلين مقررين عند الفقهاء:"},{"t":"quote","text":"وَاتَّفَقُوا عَلَى أَنَّ الْمَاءَ الَّذِي غَيَّرَتِ النَّجَاسَةُ إِمَّا طَعْمَهُ أَوْ لَوْنَهُ أَوْ رِيحَهُ أَوْ أَكْثَرَ مِنْ وَاحِدٍة مِنْ هَذِهِ الْأَوْصَافِ أَنَّهُ لَا يَجُوزُ بِهِ الْوُضُوءُ وَلَا الطُّهُورُ","src":"بداية المجتهد","loc":"١/٣٠","pre":"الأول: أن النجاسة إنما تؤثر في الماء بتغييرها له؛ قال ابن رشد:"},{"t":"quote","text":"طَهُرَ الْكَثِيرُ بِالنَّزْحِ وَطُولِ الْمُكْثِ، وَلَمْ يَطْهُرْ الْقَلِيلُ، فَإِنَّ الْكَثِيرَ لَمَّا كَانَتْ عِلَّةُ تَنْجِيسِهِ التَّغَيُّرَ زَالَ تَنْجِيسُهُ بِزَوَالِ عِلَّتِهِ، كَالْخَمْرَةِ إذَا انْقَلَبَتْ خَلًّا","src":"المغني","loc":"١/٢٨","pre":"الثاني: أن الحكم يدور مع علته، فإذا زال التغيّر زالت النجاسة؛ قال ابن قدامة:"},{"t":"h","text":"قرار هيئة كبار العلماء"},{"t":"p","text":"وقد عُرضت المسألة على هيئة كبار العلماء في دورتها الثالثة عشرة (شوال ١٣٩٨هـ)، فقرّرت ما يلي:"},{"t":"quote","text":"بناءً على ما ذكره أهل العلم من أن الماء الكثير المتغير بنجاسة يطهر إذا زال تغيره بنفسه أو بإضافة ماء طهور إليه، أو زال تغيره بطول مكث أو تأثير شمس ومرور الرياح عليه أو نحو ذلك لزوال الحكم بزوال علته","src":"الإسلام سؤال وجواب","loc":"٥/٣٧"},{"t":"quote","text":"ولذلك فإن المجلس يرى طهارتها بعد تنقيتها التنقية الكاملة بحيث تعود إلى خلقتها الأولى لا يرى فيها تغير بنجاسة في طعم ولا لون ولا ريح، ويجوز استعمالها في إزالة الأحداث والأخباث، وتحصل الطهارة بها منها، كما يجوز شربها إلا إذا كانت هناك أضرار صحية تنشأ عن استعمالها فيمتنع ذلك للمحافظة على النفس، وتفادياً للضرر، لا لنجاستها. والمجلس إذ يقرر ذلك يستحسن الاستغناء عنها في استعمالها للشرب متى وجد إلى ذلك سبيل، احتياطاً للصحة، واتقاءً للضرر، وتنزهاً عما تستقذره النفوس، وتنفر منه الطباع","src":"الإسلام سؤال وجواب","loc":"٥/٣٧"},{"t":"h","text":"الخلاصة","k":"r"},{"t":"p","text":"فالعبرة بزوال أثر النجاسة كليًّا: فإذا عاد الماء إلى خلقته الأولى، لا يظهر فيه طعم النجاسة ولا لونها ولا ريحها، فهو طهور. وأما الشرب منه فيُترك متى وُجد غيره، صيانةً للصحة وتنزّهًا عما تستقذره النفوس، لا لنجاسته."}],"refs":["بداية المجتهد (١/٣٠)","المغني (١/٢٨)","الإسلام سؤال وجواب (٥/٣٧)"],"related":["الماء القليل تقع فيه نجاسة ولم يتغير","تطهير الماء النجس"],"alts":["مياه المجاري المعالجة","الماء المكرر","تنقية مياه الصرف"]},{"n":11,"bab":"الطهارة","sub":"الآنية","title":"الأكل والشرب والوضوء في آنية الذهب والفضة","q":"هل يجوز الأكل والشرب أو الوضوء في أوانٍ من الذهب أو الفضة؟ وهل يصح الوضوء منها؟","short":"يحرم الأكل والشرب في آنية الذهب والفضة، وكذا سائر استعمالها، على الرجال والنساء؛ ومن توضأ منها أثِم وصحّ وضوؤه عند الجمهور. وأما الأواني الثمينة من غيرهما — كالبلّور والنحاس والزجاج — فمباحة عند عامة أهل العلم.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"لِأَنَّ النَّبِيَّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - قَالَ: «لَا تَشْرَبُوا فِي آنِيَةِ الذَّهَبِ وَالْفِضَّةِ، وَلَا تَأْكُلُوا فِي صِحَافِهَا فَإِنَّهَا لَهُمْ فِي الدُّنْيَا وَلَكُمْ فِي الْآخِرَةِ.» وَنَهَى عَنْ الشُّرْبِ فِي آنِيَةِ الْفِضَّةِ، وَقَالَ: «مَنْ شَرِبَ فِيهَا فِي الدُّنْيَا لَمْ يَشْرَبْ فِيهَا فِي الْآخِرَةِ.» وَقَالَ - عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ -: «الَّذِي يَشْرَبُ فِي آنِيَةِ الذَّهَبِ وَالْفِضَّةِ إنَّمَا يُجَرْجِرُ فِي بَطْنِهِ نَارَ جَهَنَّمَ» . مُتَّفَقٌ عَلَيْهِنَّ","src":"المغني","loc":"١/٥٦"},{"t":"h","text":"تحرير محل النزاع"},{"t":"quote","text":"وَلَا خِلَافَ بَيْنَ أَصْحَابِنَا فِي أَنَّ اسْتِعْمَالَ آنِيَةِ الذَّهَبِ وَالْفِضَّةِ حَرَامٌ، وَهُوَ مَذْهَبُ أَبِي حَنِيفَةَ، وَمَالِكٍ، وَالشَّافِعِيِّ، وَلَا أَعْلَمُ فِيهِ خِلَافًا","src":"المغني","loc":"١/٥٥-٥٦","pre":"اتفق الأئمة الأربعة على تحريم الأكل والشرب فيها؛ قال ابن قدامة:"},{"t":"quote","text":"وَالْعِلَّةُ فِي تَحْرِيمِ الشُّرْبِ فِيهَا مَا يَتَضَمَّنُهُ ذَلِكَ مِنْ الْفَخْرِ وَالْخُيَلَاءِ، وَكَسْرِ قُلُوبِ الْفُقَرَاءِ، وَهُوَ مَوْجُودٌ فِي الطَّهَارَةِ مِنْهَا وَاسْتِعْمَالِهَا كَيْفَمَا كَانَ، بَلْ إذَا حَرُمَ فِي غَيْرِ الْعِبَادَةِ فَفِيهَا أَوْلَى","src":"المغني","loc":"١/٥٦","pre":"وألحقوا بالأكل والشرب سائر الاستعمال؛ لأن العلة واحدة:"},{"t":"p","text":"واختلفوا في مسألتين: صحة الوضوء منها، والأواني الثمينة من غير الذهب والفضة."},{"t":"h","text":"المسألة الأولى: صحة الوضوء من آنية الذهب والفضة"},{"t":"qawl","label":"القول الأول","text":"يصح الوضوء مع الإثم، وهو قول الشافعي وأصحاب الرأي وإسحاق وابن المنذر، وأحد الوجهين عند الحنابلة."},{"t":"qawl","label":"القول الثاني","text":"لا يصح، وهو اختيار أبي بكر من الحنابلة."},{"t":"quote","text":"فَإِنْ تَوَضَّأَ مِنْهَا، أَوْ اغْتَسَلَ، فَعَلَى وَجْهَيْنِ: أَحَدهمَا تَصِحُّ طَهَارَتُهُ. وَهُوَ قَوْلُ الشَّافِعِيِّ، وَإِسْحَاقَ، وَابْنِ الْمُنْذِرِ، وَأَصْحَابِ الرَّأْيِ؛ لِأَنَّ فِعْلَ الطَّهَارَةِ وَمَاءَهَا لَا يَتَعَلَّقُ بِشَيْءٍ مِنْ ذَلِكَ، أَشْبَهَ الطَّهَارَةَ فِي الدَّارِ الْمَغْصُوبَةِ. وَالثَّانِي: لَا يَصِحُّ اخْتَارَهُ أَبُو بَكْرٍ؛ لِأَنَّهُ اسْتَعْمَلَ الْمُحَرَّمَ فِي الْعِبَادَةِ، فَلَمْ يَصِحَّ، كَالصَّلَاةِ فِي الدَّارِ الْمَغْصُوبَةِ وَالْأَوَّلُ أَصَحُّ، وَيُفَارِقُ هَذَا الصَّلَاةَ فِي الدَّارِ الْمَغْصُوبَةِ؛ لِأَنَّ أَفْعَالَ الصَّلَاةِ مِنْ الْقِيَامِ وَالْقُعُودِ وَالرُّكُوعِ وَالسُّجُودِ، فِي الدَّارِ الْمَغْصُوبَةِ؛ مُحَرَّمٌ؛ لِكَوْنِهِ تَصَرُّفًا فِي مِلْكِ غَيْرِهِ بِغَيْرِ إذْنِهِ، وَشُغْلًا لَهُ، وَأَفْعَالُ الْوُضُوءِ؛ مِنْ الْغَسْلِ، وَالْمَسْحِ، لَيْسَ بِمُحَرَّمٍ، إذْ لَيْسَ هُوَ اسْتِعْمَالًا لِلْإِنَاءِ، وَلَا تَصَرُّفًا فِيهِ، وَإِنَّمَا يَقَعُ ذَلِكَ بَعْدَ رَفْعِ الْمَاءِ مِنْ الْإِنَاءِ، وَفَصْلِهِ عَنْهُ، فَأَشْبَهَ مَا لَوْ غَرَفَ بِآنِيَةِ الْفِضَّةِ فِي إنَاءٍ غَيْرِهِ، ثُمَّ تَوَضَّأَ بِهِ؛ وَلِأَنَّ الْمَكَانَ شَرْطٌ لِلصَّلَاةِ، إذْ لَا يُمْكِنُ وُجُودُهَا فِي غَيْرِ مَكَان، وَالْإِنَاءُ لَيْسَ بِشَرْطٍ، فَأَشْبَهَ مَا لَوْ صَلَّى وَفِي يَدِهِ خَاتَمُ ذَهَبٍ","src":"المغني","loc":"١/٥٦","pre":"قال ابن قدامة:"},{"t":"h","text":"المسألة الثانية: الأواني الثمينة من غير الذهب والفضة"},{"t":"qawl","label":"القول الأول","text":"أنها مباحة، وهو قول عامة أهل العلم."},{"t":"qawl","label":"القول الثاني","text":"أن ما كان ثمينًا لنفاسة جوهره محرّم، وهو أحد قولي الشافعي؛ وكره ابن عمر رضي الله عنهما الوضوء في النحاس والصفر."},{"t":"quote","text":"فَأَمَّا سَائِرُ الْآنِيَةِ فَمُبَاحٌ اتِّخَاذُهَا وَاسْتِعْمَالُهَا، سَوَاءٌ كَانَتْ ثَمِينَةً، كَالْيَاقُوتِ وَالْبِلَّوْرِ وَالْعَقِيقِ وَالصُّفْرِ وَالْمَخْرُوطِ مِنْ الزُّجَاجِ، أَوْ غَيْرَ ثَمِينَةٍ، كَالْخَشَبِ وَالْخَزَفِ وَالْجُلُودِ. وَلَا يُكْرَهُ اسْتِعْمَالُ شَيْءٍ مِنْهَا فِي قَوْلِ عَامَّةِ أَهْلِ الْعِلْمِ، إلَّا أَنَّهُ رُوِيَ عَنْ ابْنِ عُمَرَ أَنَّهُ كَرِهَ الْوُضُوءَ فِي الصُّفْرِ وَالنُّحَاسِ وَالرَّصَاصِ وَمَا أَشْبَهَ ذَلِكَ. وَاخْتَارَ ذَلِكَ الشَّيْخُ أَبُو الْفَرَجِ الْمَقْدِسِيُّ؛ لِأَنَّ الْمَاءَ يَتَغَيَّرُ فِيهَا، وَرُوِيَ أَنَّ الْمَلَائِكَةَ تَكْرَهُ رِيحَ النُّحَاسِ، وَقَالَ الشَّافِعِيُّ فِي أَحَدِ قَوْلَيْهِ: مَا كَانَ ثَمِينًا لِنَفَاسَةِ جَوْهَرِهِ فَهُوَ مُحَرَّمٌ؛ لِأَنَّ تَحْرِيمَ الْأَثْمَانِ تَنْبِيهٌ عَلَى تَحْرِيمِ مَا هُوَ أَعْلَى مِنْهُ؛ وَلِأَنَّ فِيهِ سَرَفًا وَخُيَلَاءَ وَكَسْرَ قُلُوبِ الْفُقَرَاءِ، فَكَانَ مُحَرَّمًا كَالْأَثْمَانِ","src":"المغني","loc":"١/٥٨","pre":"قال ابن قدامة:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الراجح في المسألة الأولى صحة الوضوء مع الإثم؛ لأن الوضوء يقع بعد انفصال الماء عن الإناء، فلا يتعلق التحريم بنفس العبادة. والراجح في الثانية الإباحة؛ لأن النبي ﷺ توضأ من تَور من صُفر، والأصل في الأشياء الحلّ."},{"t":"quote","text":"وَلَنَا مَا رُوِيَ عَنْ عَبْدِ اللَّهِ بْنِ زَيْدٍ، قَالَ: «أَتَانَا رَسُولُ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - فَأَخْرَجْنَا لَهُ مَاءً فِي تَوْرٍ مِنْ صُفْرٍ، فَتَوَضَّأَ.» مُتَّفَقٌ عَلَيْهِ، وَرَوَى أَبُو دَاوُد فِي \" سُنَنِهِ \"، عَنْ عَائِشَةَ قَالَتْ: «كُنْت أَغْتَسِلُ أَنَا وَرَسُولُ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - فِي تَوْرٍ مِنْ شَبَهٍ» وَلِأَنَّ الْأَصْلَ الْحِلُّ، فَيَبْقَى عَلَيْهِ، وَلَا يَصِحُّ قِيَاسُهُ عَلَى الْأَثْمَانِ؛ لِوَجْهَيْنِ: أَحَدُهُمَا أَنَّ هَذَا لَا يَعْرِفُهُ إلَّا خَوَاصُّ النَّاسِ، فَلَا تَنْكَسِرُ قُلُوبُ الْفُقَرَاءِ بِاسْتِعْمَالِهِ، بِخِلَافِ الْأَثْمَانِ","src":"المغني","loc":"١/٥٨","pre":"قال ابن قدامة:"},{"t":"tanbih","items":[{"t":"quote","text":"وَيَحْرُمُ ذَلِكَ عَلَى الرِّجَالِ وَالنِّسَاءِ؛ لِعُمُومِ النَّصِّ فِيهِمَا، وَوُجُودِ مَعْنَى التَّحْرِيمِ فِي حَقِّهِمَا، وَإِنَّمَا أُبِيحَ التَّحَلِّي فِي حَقِّ الْمَرْأَةِ؛ لِحَاجَتِهَا إلَى التَّزَيُّنِ لِلزَّوْجِ، وَالتَّجَمُّلِ عِنْدَهُ، وَهَذَا يَخْتَصُّ الْحُلِيَّ، فَتَخْتَصُّ الْإِبَاحَةُ بِهِ","src":"المغني","loc":"١/٥٧","pre":"التحريم عامّ للرجال والنساء؛ قال ابن قدامة:"}]}],"refs":["المغني (١/٥٦)","المغني (١/٥٥-٥٦)","المغني (١/٥٨)","المغني (١/٥٧)"],"related":["الإناء المضبَّب بالفضة","آنية الكفار وثيابهم"],"alts":["الشرب في كأس من فضة","ملاعق الذهب","الأواني المذهبة"]},{"n":12,"bab":"الطهارة","sub":"الآنية","title":"الإناء المضبَّب بالفضة أو الذهب","q":"إناء انكسر فأُصلح بقطعة أو سلسلة من فضة، أو فيه شيء من الذهب أو الفضة، فهل يجوز استعماله؟","short":"يجوز استعمال الإناء الذي فيه ضبّة يسيرة من فضة للحاجة، كإصلاح الكسر، ويُتجنّب مباشرة موضع الفضة بالفم؛ وأما الكثير من الفضة، والذهب مطلقًا، فيُترك إلا لضرورة.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"وَأَمَّا الْفِضَّةُ فَيُبَاحُ مِنْهَا الْيَسِيرُ؛ لِمَا رَوَى أَنَسٌ، «أَنَّ قَدَحَ رَسُولِ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - انْكَسَرَ، فَاتَّخَذَ مَكَانَ الشَّعْبِ سِلْسِلَةً مِنْ فِضَّةٍ.» رَوَاهُ الْبُخَارِيُّ؛ وَلِأَنَّ الْحَاجَةَ تَدْعُو إلَيْهِ، وَلَيْسَ فِيهِ سَرَفٌ وَلَا خُيَلَاءُ، فَأَشْبَهَ الضَّبَّةَ مِنْ الصُّفْرِ","src":"المغني","loc":"١/٥٧-٥٨","pre":"قال ابن قدامة:"},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"يحرم الكثير من الضبّة مطلقًا، ذهبًا كانت أو فضة، ويباح اليسير من الفضة للحاجة؛ وهو قول الشافعي والحنابلة."},{"t":"qawl","label":"القول الثاني","text":"يباح المضبَّب وإن كانت الضبّة كثيرة؛ لأنها تابعة للإناء المباح، وهو قول أبي حنيفة."},{"t":"quote","text":"فَأَمَّا الْمُضَبَّبُ بِالذَّهَبِ أَوْ الْفِضَّةِ، فَإِنْ كَانَ كَثِيرًا فَهُوَ مُحَرَّمٌ بِكُلِّ حَالٍ؛ ذَهَبًا كَانَ أَوْ فِضَّةً، لَحَاجَةٍ أَوْ لِغَيْرِهَا. وَبِهَذَا قَالَ الشَّافِعِيُّ. وَأَبَاحَ أَبُو حَنِيفَةَ الْمُضَبَّبَ، وَإِنْ كَانَ كَثِيرًا؛ لِأَنَّهُ صَارَ تَابِعًا لِلْمُبَاحِ، فَأَشْبَهَ الْمُضَبَّبَ بِالْيَسِيرِ وَلَنَا أَنَّ هَذَا فِيهِ سَرَفٌ وَخُيَلَاءُ، فَأَشْبَهَ الْخَالِصَ، وَيَبْطُلُ مَا قَالَهُ بِمَا إذَا اتَّخَذَ أَبْوَابًا مِنْ فِضَّةٍ أَوْ ذَهَبٍ، أَوْ رُفُوفًا، فَإِنَّهُ يَحْرُمُ، وَإِنْ كَانَ تَابِعًا، وَفَارَقَ الْيَسِيرَ، فَإِنَّهُ لَا يُوجَدُ فِيهِ الْمَعْنَى الْمُحَرَّمُ. إذَا ثَبَتَ هَذَا، فَاخْتَلَفَ أَصْحَابُنَا؛ فَقَالَ أَبُو بَكْرٍ يُبَاحُ الْيَسِيرُ مِنْ الذَّهَبِ وَالْفِضَّةِ؛ لِمَا ذَكَرْنَا، وَأَكْثَرُ أَصْحَابِنَا عَلَى أَنَّهُ لَا يُبَاحُ الْيَسِيرُ مِنْ الذَّهَبِ، وَلَا يُبَاحُ مِنْهُ إلَّا مَا دَعَتْ الضَّرُورَةُ إلَيْهِ، كَأَنْفِ الذَّهَبِ، وَمَا رَبَطَ بِهِ أَسْنَانَهُ","src":"المغني","loc":"١/٥٧","pre":"قال ابن قدامة:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الذي يدل عليه الحديث إباحة اليسير من الفضة للحاجة؛ لأن النبي ﷺ أصلح قدحه بسلسلة من فضة. وأما الكثير فإن فيه معنى الفخر والخيلاء الذي من أجله حُرّمت الآنية، فالأولى تركه، خروجًا من الخلاف."},{"t":"quote","text":"قَالَ الْقَاضِي: وَيُبَاحُ ذَلِكَ مَعَ الْحَاجَةِ وَعَدَمِهَا؛ لِمَا ذَكَرْنَا، إلَّا أَنَّ مَا يُسْتَعْمَلُ مِنْ ذَلِكَ لَا يُبَاحُ كَالْحَلْقَةِ، وَمَا لَا يُسْتَعْمَلُ كَالضَّبَّةِ يُبَاحُ. وَقَالَ أَبُو الْخَطَّابِ لَا يُبَاحُ الْيَسِيرُ إلَّا لِحَاجَةٍ؛ لِأَنَّ الْخَبَرَ إنَّمَا وَرَدَ فِي تَشْعِيبِ الْقَدَحِ فِي مَوْضِعِ الْكَسْرِ، وَهُوَ لِحَاجَةٍ، وَمَعْنَى الْحَاجَةِ أَنْ تَدْعُوَ الْحَاجَةُ إلَى مَا فَعَلَهُ بِهِ، وَإِنْ كَانَ غَيْرُهُ يَقُومُ مَقَامَهُ، وَتُكْرَهُ مُبَاشَرَةُ مَوْضِعِ الْفِضَّةِ بِالِاسْتِعْمَالِ؛ كَيْ لَا يَكُونَ مُسْتَعْمِلًا لَهَا","src":"المغني","loc":"١/٥٨","pre":"وقد اختلف الحنابلة في اشتراط الحاجة؛ قال ابن قدامة:"}],"refs":["المغني (١/٥٧-٥٨)","المغني (١/٥٧)","المغني (١/٥٨)"],"related":["الأكل والشرب والوضوء في آنية الذهب والفضة"],"alts":["إصلاح الإناء بالفضة","الكأس المطلي بالفضة","الضبة"]},{"n":13,"bab":"الطهارة","sub":"الآنية","title":"جلد الميتة إذا دُبغ","q":"هل يطهر جلد الميتة بالدباغ، فيجوز استعماله في القِرَب والأحذية والملابس والصلاة عليه؟","short":"نعم، جلد الميتة يطهر بالدباغ على الراجح، فيجوز استعماله في كل شيء إلا الأكل؛ وهذا قول جمهور العلماء، ومنهم الحنفية والشافعية؛ واستثنى الحنفية جلد الخنزير، والشافعية جلد الكلب والخنزير.","body":[{"t":"h","text":"تحرير محل النزاع"},{"t":"quote","text":"لَا يَخْتَلِفُ الْمَذْهَبُ فِي نَجَاسَةِ الْمَيْتَةِ قَبْلَ الدَّبْغِ، وَلَا نَعْلَمُ أَحَدًا خَالَفَ فِيهِ","src":"المغني","loc":"١/٤٩","pre":"جلد الميتة قبل الدباغ نجس بالاتفاق؛ قال ابن قدامة:"},{"t":"p","text":"واختلفوا فيه بعد الدباغ:"},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"لا يطهر بالدباغ، وهو المشهور عند الحنابلة، وإحدى الروايتين عن مالك."},{"t":"qawl","label":"القول الثاني","text":"يطهر بالدباغ جلدُ ما كان طاهرًا في حال الحياة، وهو قول الشافعي ورواية عن أحمد؛ فيطهر عنده كل جلد إلا جلد الكلب والخنزير."},{"t":"qawl","label":"القول الثالث","text":"يطهر كل جلد إلا جلد الخنزير، وهو قول أبي حنيفة."},{"t":"qawl","label":"القول الرابع","text":"يطهر كل جلد، وهو محكيّ عن أبي يوسف، ورواية عن مالك."},{"t":"quote","text":"وَأَمَّا بَعْدَ الدَّبْغِ فَالْمَشْهُورُ فِي الْمَذْهَبِ أَنَّهُ نَجِسٌ أَيْضًا، وَهُوَ إحْدَى الرِّوَايَتَيْنِ عَنْ مَالِكٍ، وَيُرْوَى ذَلِكَ عَنْ عُمَرَ وَابْنِهِ عَبْدِ اللَّهِ بْنِ عُمَرَ - رَضِيَ اللَّهُ عَنْهُمَا - وَعِمْرَانَ بْنِ حُصَيْنٍ، وَعَائِشَةَ - رَضِيَ اللَّهُ عَنْهُمْ -. وَعَنْ أَحْمَدَ رِوَايَةٌ أُخْرَى: أَنَّهُ يَطْهُرُ مِنْهَا جِلْدُ مَا كَانَ طَاهِرًا فِي حَالِ الْحَيَاةِ. وَرُوِيَ نَحْوُ هَذَا عَنْ عَطَاءٍ، وَالْحَسَنِ، وَالشَّعْبِيِّ، وَالنَّخَعِيِّ، وَقَتَادَةَ، وَيَحْيَى الْأَنْصَارِيِّ، وَسَعِيدِ بْنِ جُبَيْرٍ، وَالْأَوْزَاعِيِّ، وَاللَّيْثِ، وَالثَّوْرِيِّ، وَابْنِ الْمُبَارَكِ، وَإِسْحَاقَ، وَرُوِيَ ذَلِكَ عَنْ عُمَرَ، وَابْنِ عَبَّاسٍ، وَابْنِ مَسْعُودٍ، وَعَائِشَةَ - رَضِيَ اللَّهُ عَنْهُمْ -، مَعَ اخْتِلَافِهِمْ فِيمَا هُوَ طَاهِرٌ فِي الْحَيَاةِ، وَهُوَ مَذْهَبُ الشَّافِعِيِّ، وَهُوَ يَرَى طَهَارَةَ الْحَيَوَانَاتِ كُلِّهَا، إلَّا الْكَلْبَ وَالْخِنْزِيرَ، فَيَطْهُرُ عِنْدَهُ كُلُّ جِلْدٍ إلَّا جِلْدَهُمَا. وَلَهُ فِي جِلْدِ الْآدَمِيِّ وَجْهَانِ. وَقَالَ أَبُو حَنِيفَةَ: يَطْهُرُ كُلُّ جِلْدٍ بِالدَّبْغِ إلَّا جِلْدَ الْخِنْزِيرِ. وَحُكِيَ عَنْ أَبِي يُوسُفَ: أَنَّهُ يَطْهُرُ كُلُّ جِلْدٍ. وَهُوَ رِوَايَةٌ عَنْ مَالِكٍ، وَمَذْهَبُ مَنْ حَكَمَ بِطَهَارَةِ الْحَيَوَانَاتِ كُلِّهَا؛ لِأَنَّ النَّبِيَّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - قَالَ: «إذَا دُبِغَ الْإِهَابُ فَقَدْ طَهُرَ.» مُتَّفَقٌ عَلَيْهِ؛ وَلِأَنَّ رَسُولَ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - «وَجَدَ شَاةً مَيِّتَةً أُعْطِيَتْهَا مَوْلَاةٌ لِمَيْمُونَةَ مِنْ الصَّدَقَةِ. فَقَالَ رَسُولُ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - هَلَّا انْتَفَعْتُمْ بِجِلْدِهَا؟ قَالُوا: إنَّهَا مَيْتَةٌ. قَالَ: إنَّمَا حَرُمَ أَكْلُهَا.» وَفِي لَفْظٍ: «أَلَا أَخَذُوا إهَابَهَا فَدَبَغُوهُ فَانْتَفَعُوا بِهِ» . مُتَّفَقٌ عَلَيْهِ؛ وَلِأَنَّهُ إنَّمَا نَجُسَ بِاتِّصَالِ الدِّمَاءِ وَالرُّطُوبَاتِ بِهِ بِالْمَوْتِ، وَالدَّبْغُ يُزِيلُ ذَلِكَ، فَيَرْتَدُّ الْجِلْدُ إلَى مَا كَانَ عَلَيْهِ فِي حَالِ الْحَيَاةِ","src":"المغني","loc":"١/٤٩","pre":"قال ابن قدامة:"},{"t":"quote","text":"وَلَنَا مَا رَوَى عَبْدُ اللَّهِ بْنُ عُكَيْمٍ، «أَنَّ النَّبِيَّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - كَتَبَ إلَى جُهَيْنَةَ إنِّي كُنْت رَخَّصْت لَكُمْ فِي جُلُودِ الْمَيْتَةِ، فَإِذَا جَاءَكُمْ كِتَابِي هَذَا فَلَا تَنْتَفِعُوا مِنْ الْمَيْتَةِ بِإِهَابٍ وَلَا عَصَبٍ","src":"المغني","loc":"١/٤٩","pre":"ودليل من قال لا يطهر:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الراجح أن الجلد يطهر بالدباغ؛ لحديث ابن عباس رضي الله عنهما في صحيح مسلم:"},{"t":"quote","text":"وَعَنْ ابْنِ عَبَّاسٍ - رَضِيَ اللَّهُ عَنْهُمَا - قَالَ: قَالَ رَسُولُ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - «إذَا دُبِغَ الْإِهَابُ فَقَدْ طَهُرَ» أَخْرَجَهُ مُسْلِمٌ - وَعِنْدَ الْأَرْبَعَةِ \" أَيُّمَا إهَابٍ دُبِغَ","src":"سبل السلام","loc":"١/٤١"},{"t":"quote","text":"أَنَّهُ حَدِيثٌ مُضْطَرِبٌ فِي سَنَدِهِ، فَإِنَّهُ رُوِيَ عَنْ كِتَابِ النَّبِيِّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -، وَتَارَةً عَنْ مَشَايِخَ مِنْ جُهَيْنَةَ عَمَّنْ قَرَأَ كِتَابَ النَّبِيِّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -، وَمُضْطَرِبٌ أَيْضًا فِي مَتْنِهِ، فَرُوِيَ مِنْ غَيْرِ تَقْيِيدٍ فِي رِوَايَةِ الْأَكْلِ، وَرُوِيَ بِالتَّقْيِيدِ بِشَهْرٍ أَوْ شَهْرَيْنِ أَوْ أَرْبَعِينَ يَوْمًا أَوْ ثَلَاثَةِ أَيَّامٍ، ثُمَّ إنَّهُ مُعَلٌّ أَيْضًا بِالْإِرْسَالِ، فَإِنَّهُ لَمْ يَسْمَعْهُ \" عَبْدُ اللَّهِ بْنُ عُكَيْمٍ \" مِنْهُ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -، وَمُعَلٌّ بِالِانْقِطَاعِ؛ لِأَنَّهُ لَمْ يَسْمَعْهُ \" عَبْدُ الرَّحْمَنِ بْنُ أَبِي لَيْلَى \" مِنْ \" ابْنِ عُكَيْمٍ \"، وَلِذَلِكَ تَرَكَ أَحْمَدُ بْنُ حَنْبَلٍ الْقَوْلَ بِهِ آخِرًا، وَكَانَ يَذْهَبُ إلَيْهِ أَوَّلًا كَمَا قَالَ عَنْهُ التِّرْمِذِيُّ. وَ (ثَانِيًا) : بِأَنَّهُ لَا يَقْوَى عَلَى النَّسْخِ؛ لِأَنَّ حَدِيثَ الدِّبَاغِ أَصَحُّ؛ فَإِنَّهُ مِمَّا اتَّفَقَ عَلَيْهِ الشَّيْخَانِ، وَأَخْرَجَ مُسْلِمٌ وَرُوِيَ مِنْ طُرُقٍ مُتَعَدِّدَةٍ فِي مَعْنَاهُ عِدَّةُ أَحَادِيثَ عَنْ جَمَاعَةٍ مِنْ الصَّحَابَةِ، فَعَنْ ابْنِ عَبَّاسٍ حَدِيثَانِ، وَعَنْ أُمِّ سَلَمَةَ ثَلَاثَةٌ، وَعَنْ أَنَسٍ حَدِيثَانِ، وَعَنْ سَلَمَةَ بْنِ الْمُحَبِّقِ وَعَائِشَةَ وَالْمُغِيرَةِ وَأَبِي أُمَامَةَ وَابْنِ مَسْعُودٍ، وَلِأَنَّ النَّاسِخَ لَا بُدَّ مِنْ تَحْقِيقِ تَأَخُّرِهِ وَلَا دَلِيلَ عَلَى تَأَخُّرِ حَدِيثِ ابْنِ عُكَيْمٍ، وَرِوَايَةُ التَّارِيخِ فِيهِ بِشَهْرٍ أَوْ شَهْرَيْنِ مُعَلَّةٌ، فَلَا تَقُومُ بِهَا حُجَّةٌ عَلَى النَّسْخِ، عَلَى أَنَّهَا لَوْ كَانَتْ رِوَايَةُ التَّارِيخِ صَحِيحَةً مَا دَلَّتْ عَلَى أَنَّهُ آخِرُ الْأَمْرَيْنِ جَزْمًا، وَلَا يُقَالُ: فَإِذَا لَمْ يَتِمَّ النَّسْخُ تَعَارَضَ الْحَدِيثَانِ، حَدِيثُ عَبْدِ اللَّهِ بْنِ عُكَيْمٍ وَحَدِيثُ ابْنِ عَبَّاسٍ وَمَنْ مَعَهُ، وَمَعَ التَّعَارُضِ يُرْجَعُ إلَى التَّرْجِيحِ أَوْ الْوَقْفِ،؛ لِأَنَّا نَقُولُ لَا تَعَارُضَ إلَّا مَعَ الِاسْتِوَاءِ، وَهُوَ مَفْقُودٌ كَمَا عَرَفْت مِنْ صِحَّةِ حَدِيثِ ابْنِ عَبَّاسٍ، وَكَثْرَةِ مَنْ مَعَهُ مِنْ الرُّوَاةِ، وَعَدَمِ ذَلِكَ فِي حَدِيثِ ابْنِ عُكَيْمٍ","src":"سبل السلام","loc":"١/٤٢","pre":"وأما حديث عبد الله بن عُكيم فقد أجاب عنه الصنعاني بأجوبة، فقال: الأول:"},{"t":"tanbih","items":[{"t":"p","text":"لا يحلّ أكل جلد الميتة ولو دُبغ؛ لقوله ﷺ: «إنما حرم أكلها»، وهو قول أكثر أهل العلم (المغني ١/٥١)."},{"t":"quote","text":"وَيَجُوزُ بَيْعُهُ، وَإِجَارَتُهُ، وَالِانْتِفَاعُ بِهِ فِي كُلِّ مَا يُمْكِنُ الِانْتِفَاعُ بِهِ فِيهِ، سِوَى الْأَكْلِ؛ لِأَنَّهُ صَارَ بِمَنْزِلَةِ الْمُذَكَّى فِي غَيْرِ الْأَكْلِ وَلَا يَجُوزُ بَيْعُهُ قَبْلَ دَبْغِهِ؛ لِأَنَّهُ نَجِسٌ، مُتَّفَقٌ عَلَى نَجَاسَةِ عَيْنِهِ، فَأَشْبَهَ الْخِنْزِيرَ","src":"المغني","loc":"١/٥١","pre":"قال ابن قدامة في الجلد المدبوغ عند من قال بطهارته:"}]}],"refs":["المغني (١/٤٩)","سبل السلام (١/٤١)","سبل السلام (١/٤٢)","المغني (١/٥١)"],"related":["عظم الميتة وشعرها وصوفها"],"alts":["دباغ الجلد","جلود الحيوانات الميتة","الصلاة على جلد مدبوغ"]},{"n":14,"bab":"الطهارة","sub":"الآنية","title":"عظم الميتة وقرنها وشعرها وصوفها","q":"هل عظم الميتة وقرنها وشعرها وصوفها وريشها طاهر، فيجوز الانتفاع به؟","short":"شعر الميتة وصوفها ووبرها وريشها طاهر عند جمهور العلماء؛ وأما العظم والقرن والظفر ففيها خلاف، والراجح طهارتها أيضًا، وهو قول أبي حنيفة، واختاره ابن تيمية.","body":[{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"أَمَّا عَظْمُ الْمَيْتَةِ وَقَرْنُهَا؛ وَظُفْرُهَا؛ وَمَا هُوَ مِنْ جِنْسِ ذَلِكَ كَالْحَافِرِ وَنَحْوِهِ وَشَعْرِهَا وَرِيشِهَا؛ وَوَبَرِهَا: فَفِي هَذَيْنَ النَّوْعَيْنِ لِلْعُلَمَاءِ ثَلَاثَةُ أَقْوَالٍ: أَحَدُهَا: نَجَاسَةُ الْجَمِيعِ. كَقَوْلِ الشَّافِعِيِّ فِي الْمَشْهُورِ عَنْهُ؛ وَذَلِكَ رِوَايَةٌ عَنْ أَحْمَد. وَالثَّانِي: أَنَّ الْعِظَامَ وَنَحْوَهَا نَجِسَةٌ وَالشُّعُورَ وَنَحْوَهَا طَاهِرَةٌ. وَهَذَا هُوَ الْمَشْهُورُ مِنْ مَذْهَبِ مَالِكٍ وَأَحْمَد. وَالثَّالِثُ: أَنَّ الْجَمِيعَ طَاهِرٌ. كَقَوْلِ أَبِي حَنِيفَةَ؛ وَهُوَ قَوْلٌ فِي مَذْهَبِ مَالِكٍ وَأَحْمَد","src":"مجموع الفتاوى","loc":"٢١/٩٦-٩٧","pre":"جمع ابن تيمية الأقوال في المسألة فقال:"},{"t":"p","text":"فالأقوال ثلاثة:"},{"t":"qawl","label":"القول الأول","text":"نجاسة الجميع: العظم والشعر وما في معناهما، وهو المشهور عن الشافعي، ورواية عن أحمد."},{"t":"qawl","label":"القول الثاني","text":"نجاسة العظام ونحوها، وطهارة الشعور ونحوها، وهو المشهور من مذهب مالك وأحمد."},{"t":"quote","text":"وَجُمْلَةُ ذَلِكَ، أَنَّ عِظَامَ الْمَيْتَةِ نَجِسَةٌ، سَوَاءٌ كَانَتْ مَيْتَةَ مَا يُؤْكَلُ لَحْمُهُ، أَوْ مَا لَا يُؤْكَلُ لَحْمُهُ، كَالْفِيَلَةِ، وَلَا يَطْهُرُ بِحَالٍ، وَهَذَا مَذْهَبُ مَالِكٍ، وَالشَّافِعِيِّ، وَإِسْحَاقَ، وَكَرِهَ عَطَاءٌ، وَطَاوُسٌ، وَالْحَسَنُ، وَعُمَرُ بْنُ عَبْدِ الْعَزِيزِ - رَضِيَ اللَّهُ عَنْهُمْ - عِظَامَ الْفِيَلَةِ، وَرَخَّصَ فِي الِانْتِفَاعِ بِهَا مُحَمَّدُ بْنُ سِيرِينَ، وَغَيْرُهُ، وَابْنُ جُرَيْجٍ؛ لِمَا رَوَى أَبُو دَاوُد بِإِسْنَادِهِ عَنْ ثَوْبَانِ، أَنَّ رَسُولَ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - قَالَ: «اشْتَرِ لِفَاطِمَةَ - رَضِيَ اللَّهُ عَنْهَا - قِلَادَةً مِنْ عَصَبٍ وَسِوَارَيْنِ مِنْ عَاجٍ» . وَلَنَا قَوْلُ اللَّهِ تَعَالَى: {حُرِّمَتْ عَلَيْكُمُ الْمَيْتَةُ} المائدة: 3 وَالْعَظْمُ مِنْ جُمْلَتِهَا، فَيَكُونُ مُحَرَّمًا، وَالْفِيلُ لَا يُؤْكَلُ لَحْمُهُ فَهُوَ نَجِسٌ عَلَى كُلِّ حَالٍ، وَأَمَّا الْحَدِيثُ، فَقَالَ الْخَطَّابِيُّ: قَالَ الْأَصْمَعِيُّ: الْعَاجُ الذَّبْلُ، وَيُقَال: هُوَ عَظْمُ ظَهْرِ السُّلَحْفَاةِ الْبَحْرِيَّةِ. وَذَهَبَ مَالِكٌ إلَى أَنَّ الْفِيلَ إنَّ ذُكِّيَ فَعَظْمُهُ طَاهِرٌ، وَإِلَّا فَهُوَ نَجِسٌ؛ لِأَنَّ الْفِيلَ مَأْكُولٌ عِنْدَهُ، وَهُوَ غَيْرُ صَحِيحٍ؛ لِأَنَّ النَّبِيَّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - «نَهَى عَنْ أَكْلِ كُلِّ ذِي نَابٍ مِنْ السِّبَاعِ» رَوَاهُ مُسْلِمٌ وَالْفِيلُ أَعْظَمُهَا نَابًا فَأَمَّا عِظَامُ بَقِيَّةِ الْمَيْتَاتِ، فَذَهَبَ الثَّوْرِيُّ، وَأَبُو حَنِيفَةَ، إلَى طَهَارَتِهَا؛ لِأَنَّ الْمَوْتَ لَا يُحِلُّهَا فَلَا تَنْجُسُ بِهِ، كَالشَّعْرِ؛ وَلِأَنَّ عِلَّةَ التَّنْجِيسِ فِي اللَّحْمِ وَالْجِلْدِ اتِّصَالُ الدِّمَاءِ وَالرُّطُوبَاتِ بِهِ، وَلَا يُوجَدُ ذَلِكَ فِي الْعِظَامِ وَلَنَا قَوْلُ اللَّهِ تَعَالَى {قَالَ مَنْ يُحْيِي الْعِظَامَ وَهِيَ رَمِيمٌ} يس: 78 {قُلْ يُحْيِيهَا الَّذِي أَنْشَأَهَا أَوَّلَ مَرَّةٍ وَهُوَ بِكُلِّ خَلْقٍ عَلِيمٌ} يس: 79 وَمَا يَحْيَا فَهُوَ يَمُوتُ؛ وَلِأَنَّ دَلِيلَ الْحَيَاةِ الْإِحْسَاسُ وَالْأَلَمُ، وَالْأَلَمُ فِي الْعَظْمِ أَشَدُّ مِنْ الْأَلَمِ فِي اللَّحْمِ وَالْجِلْدِ، وَالضِّرْسُ يَأْلَمُ، وَيَلْحَقُهُ الضِّرْسُ، وَيُحِسُّ بِبَرْدِ الْمَاءِ وَحَرَارَتِهِ، وَمَا تَحِلُّهُ الْحَيَاةُ يَحِلُّهُ الْمَوْتُ؛ إذْ كَانَ الْمَوْتُ مُفَارَقَةَ الْحَيَاةِ، وَمَا يَحُلُّهُ الْمَوْتُ يَنْجُسُ بِهِ كَاللَّحْمِ","src":"المغني","loc":"١/٥٣-٥٤","pre":"قال ابن قدامة في دليل نجاسة العظام:"},{"t":"qawl","label":"القول الثالث","text":"طهارة الجميع، وهو قول أبي حنيفة والثوري، وقول في مذهب مالك وأحمد."},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"أما الشعر والصوف فطهارته قول الجمهور؛ لأنه لا تحله الحياة الحيوانية، ولهذا يجوز جزّه من الحيوان الحي، فلا ينجس بموته."},{"t":"quote","text":"وَلِأَنَّهُ لَا تَفْتَقِرُ طَهَارَةٌ مُنْفَصِلَةٌ إلَى ذَكَاةِ أَصْلِهِ، فَلَمْ يَنْجُسْ بِمَوْتِهِ، كَأَجْزَاءِ السَّمَكِ وَالْجَرَادِ؛ وَلِأَنَّهُ لَا يَحُلُّهُ الْمَوْتُ فَلَمْ يَنْجُسُ بِمَوْتِ الْحَيَوَانِ، كَبَيْضِهِ، وَالدَّلِيلُ عَلَى أَنَّهُ لَا حَيَاةَ فِيهِ، أَنَّهُ لَا يُحِسُّ وَلَا يَأْلَمُ، وَهُمَا دَلِيلَا الْحَيَاةِ، وَلَوْ انْفَصَلَ فِي الْحَيَاةِ كَانَ طَاهِرًا، وَلَوْ كَانَتْ فِيهِ حَيَاةٌ لَنَجِسَ بِفَصْلِهِ؛ لِقَوْلِ النَّبِيِّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -: «مَا أُبِينَ مِنْ حَيٍّ فَهُوَ مَيِّتٌ.» رَوَاهُ أَبُو دَاوُد بِمَعْنَاهُ، وَمَا ذَكَرُوهُ يُنْتَقَضُ بِالْبَيْضِ، وَيُفَارِقُ الْأَعْضَاءَ، فَإِنَّ فِيهَا حَيَاةً، وَتَنْجُسُ بِفَصْلِهَا فِي حَيَاةِ الْحَيَوَانِ، وَالنُّمُوُّ بِمُجَرَّدِهِ لَيْسَ بِدَلِيلِ الْحَيَاةِ، فَإِنَّ الْحَشِيشَ يَنْمُو، وَلَا يَنْجُسُ","src":"المغني","loc":"١/٥٩","pre":"قال ابن قدامة:"},{"t":"p","text":"وأما العظم والقرن والظفر فالراجح طهارتها كذلك، وهو قول الحنفية، وقد صوّبه ابن تيمية فقال:"},{"t":"quote","text":"وَهَذَا الْقَوْلُ هُوَ الصَّوَابُ؛ وَذَلِكَ لِأَنَّ الْأَصْلَ فِيهَا الطَّهَارَةُ؛ وَلَا دَلِيلَ عَلَى النَّجَاسَةِ. وَأَيْضًا فَإِنَّ هَذِهِ الْأَعْيَانَ هِيَ مِنْ الطَّيِّبَاتِ لَيْسَتْ مِنْ الْخَبَائِثِ فَتَدْخُلُ فِي آيَةِ التَّحْلِيلِ؛ وَذَلِكَ لِأَنَّهَا لَمْ تَدْخُلْ فِيمَا حَرَّمَهُ اللَّهُ مِنْ الْخَبَائِثِ لَا لَفْظًا وَلَا مَعْنًى","src":"مجموع الفتاوى","loc":"٢١/٩٧"},{"t":"tanbih","items":[{"t":"p","text":"ما قُطع من البهيمة وهي حية مما تحلّه الحياة — كالسنام والألية — فهو ميتة؛ بخلاف الشعر والصوف إذا جُزّ منها، فهو طاهر بالاتفاق."}]}],"refs":["مجموع الفتاوى (٢١/٩٦-٩٧)","المغني (١/٥٣-٥٤)","المغني (١/٥٩)","مجموع الفتاوى (٢١/٩٧)"],"related":["جلد الميتة إذا دُبغ"],"alts":["العاج","أمشاط العظم","الصوف والشعر من الحيوان الميت"]},{"n":15,"bab":"الطهارة","sub":"الآنية","title":"آنية الكفار وثيابهم","q":"هل يجوز الأكل والشرب في أواني غير المسلمين، أو لبس ثيابهم والصلاة فيها؟","short":"أواني أهل الكتاب وغيرهم من الكفار وثيابهم طاهرة يجوز استعمالها ما لم تُعلم نجاستها؛ لأن الأصل الطهارة. والأولى غسل الأواني التي يُطبخ فيها الخنزير أو يُشرب فيها الخمر قبل استعمالها، فإن تُيقّنت نجاستها وجب غسلها.","body":[{"t":"h","text":"الدليل من القرآن والسنة"},{"t":"aya","text":"وَطَعَامُ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ حِلٌّ لَّكُمْ وَطَعَامُكُمْ حِلٌّ لَّهُمْ","ref":"المائدة: ٥"},{"t":"quote","text":"وَرُوِيَ أَنَّ «النَّبِيَّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - أَضَافَهُ يَهُودِيٌّ بِخُبْزٍ وَإِهَالَةٍ سَنِخَةٍ.» رَوَاهُ الْإِمَامُ أَحْمَدُ، فِي \" الْمُسْنَدِ \" وَكِتَابِ \" الزُّهْدِ \"، وَتَوَضَّأَ عُمَرُ مِنْ جَرَّةِ نَصْرَانِيَّةٍ","src":"المغني","loc":"١/٦١"},{"t":"quote","text":"قُلْت «يَا رَسُولَ اللَّهِ، إنَّا بِأَرْضِ قَوْمٍ أَهْلِ كِتَابٍ، أَفَنَأْكُلُ فِي آنِيَتِهِمْ؟ فَقَالَ رَسُولُ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -: إنْ وَجَدْتُمْ غَيْرَهَا فَلَا تَأْكُلُوا فِيهَا، وَإِنْ لَمْ تَجِدُوا غَيْرَهَا فَاغْسِلُوهَا وَكُلُوا فِيهَا» مُتَّفَقٌ عَلَيْهِ","src":"المغني","loc":"١/٦١","pre":"وعن أبي ثعلبة الخشني رضي الله عنه قال:"},{"t":"h","text":"أقوال العلماء"},{"t":"p","text":"أما أواني أهل الكتاب فاتفق العلماء على جواز استعمالها ما لم تُتيقّن نجاستها، واختلفوا في كراهة ذلك؛ وأما أواني غير أهل الكتاب ففيها قولان:"},{"t":"qawl","label":"القول الأول","text":"أنها طاهرة مباحة الاستعمال ما لم تُتيقّن نجاستها، وهو مذهب الشافعي، واختاره أبو الخطاب من الحنابلة."},{"t":"qawl","label":"القول الثاني","text":"لا يُستعمل ما استعملوه من آنيتهم في أطعمتهم إلا بعد غسله، وهو قول القاضي أبي يعلى، وظاهر كلام أحمد."},{"t":"quote","text":"الضَّرْبُ الثَّانِي: غَيْرُ أَهْلِ الْكِتَابِ، وَهُمْ الْمَجُوسُ، وَعَبَدَةُ الْأَوْثَانِ، وَنَحْوُهُمْ، فَحُكْمُ ثِيَابِهِمْ حُكْمُ ثِيَابِ أَهْلِ الذِّمَّةِ، وَأَمَّا أَوَانِيهِمْ، فَقَالَ الْقَاضِي: لَا يُسْتَعْمَلُ مَا اسْتَعْمَلُوهُ مِنْ آنِيَتِهِمْ؛ لِأَنَّ أَوَانِيَهُمْ لَا تَخْلُو مِنْ أَطْعِمَتِهِمْ، وَذَبَائِحُهُمْ مَيْتَةٌ، فَلَا تَخْلُو أَوَانِيهِمْ مِنْ وَضْعِهَا فِيهَا. وَقَالَ أَبُو الْخَطَّابِ حُكْمُهُمْ حُكْمُ أَهْلِ الْكِتَابِ، وَثِيَابُهُمْ وَأَوَانِيهِمْ طَاهِرَةٌ، مُبَاحَةُ الِاسْتِعْمَالِ، مَا لَمْ يَتَيَقَّنْ نَجَاسَتَهَا، وَهُوَ مَذْهَبُ الشَّافِعِيِّ؛ «لِأَنَّ النَّبِيَّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - وَأَصْحَابَهُ تَوَضَّئُوا مِنْ مَزَادَةِ مُشْرِكَةٍ» مُتَّفَقٌ عَلَيْهِ؛ وَلِأَنَّ الْأَصْلَ الطَّهَارَةُ، فَلَا تَزُولُ بِالشَّكِّ. وَظَاهِرُ كَلَامِ أَحْمَدَ، - رَحِمَهُ اللَّهُ -، مِثْلُ قَوْلِ الْقَاضِي، فَإِنَّهُ قَالَ فِي الْمَجُوسِ: لَا يُؤْكَلُ مِنْ طَعَامِهِمْ إلَّا الْفَاكِهَةُ؛ لِأَنَّ الظَّاهِرَ نَجَاسَةُ آنِيَتِهِمْ الْمُسْتَعْمَلَةِ فِي أَطْعِمَتِهِمْ، فَأَشْبَهَتْ السَّرَاوِيلَاتِ مِنْ ثِيَابِهِمْ. وَمَنْ يَأْكُلُ الْخِنْزِيرَ مِنْ النَّصَارَى، فِي مَوْضِعٍ يُمْكِنُهُمْ أَكْلُهُ، أَوْ يَأْكُلُ الْمِيتَةَ، أَوْ يَذْبَحُ بِالسِّنِّ وَالظُّفْرِ وَنَحْوِهِ، فَحُكْمُهُ حُكْمُ غَيْرِ أَهْلِ الْكِتَابِ؛ لِاتِّفَاقِهِمْ فِي نَجَاسَةِ أَطْعِمَتِهِمْ. وَمَتَى شَكَّ فِي الْإِنَاءِ؛ هَلْ اسْتَعْمَلُوهُ فِي أَطْعِمَتِهِمْ، أَوْ لَمْ يَسْتَعْمِلُوهُ، فَهُوَ طَاهِرٌ؛ لِأَنَّ الْأَصْلَ طَهَارَتُهُ","src":"المغني","loc":"١/٦٢","pre":"قال ابن قدامة:"},{"t":"h","text":"ثيابهم"},{"t":"quote","text":"وَلَا نَعْلَمُ خِلَافًا بَيْنَ أَهْلِ الْعِلْمِ فِي إبَاحَةِ الصَّلَاةِ فِي الثَّوْبِ الَّذِي يَنْسِجُهُ الْكُفَّارُ؛ فَإِنَّ النَّبِيَّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - وَأَصْحَابَهُ، إنَّمَا كَانَ لِبَاسُهُمْ مِنْ نَسْجِ الْكُفَّارِ. فَأَمَّا ثِيَابُهُمْ، الَّتِي يَلْبَسُونَهَا، فَأَبَاحَ الصَّلَاةَ فِيهَا الثَّوْرِيُّ، وَأَصْحَابُ الرَّأْيِ، وَقَالَ مَالِكٌ فِي ثَوْبِ الْكُفَّارِ: يَلْبَسُهُ عَلَى كُلِّ حَالٍ، وَإِنْ صَلَّى فِيهِ يُعِيدُ، مَا دَامَ فِي الْوَقْتِ. وَلَنَا أَنَّ الْأَصْلَ الطَّهَارَةُ، وَلَمْ تَتَرَجَّحْ جِهَةُ التَّنْجِيسِ فِيهِ، فَأَشْبَهَ مَا نَسَجَهُ الْكُفَّارُ","src":"المغني","loc":"١/٦٢","pre":"قال ابن قدامة:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الراجح أن الأصل في أوانيهم وثيابهم الطهارة، فلا تزول بالشك؛ وقد توضأ النبي ﷺ وأصحابه من مزادة امرأة مشركة. وحديث أبي ثعلبة محمول على من عُرفوا بالأكل في آنيتهم مما حرّمه الله، فإن لم يوجد غيرها غُسلت ثم استُعملت."}],"refs":["المغني (١/٦١)","المغني (١/٦٢)"],"related":["الأكل والشرب والوضوء في آنية الذهب والفضة"],"alts":["أواني غير المسلمين","الأكل في مطاعم غير المسلمين","لبس ثياب الكفار"]},{"n":16,"bab":"الطهارة","sub":"سنن الفطرة والسواك","title":"حكم الختان ووقته","q":"ما حكم الختان؟ وهل هو واجب أو سنة؟ ومتى يُختن الصبي؟ وما حكم من أسلم كبيرًا؟","short":"الختان من سنن الفطرة باتفاق، واختلفوا في وجوبه: فأوجبه الشافعي، وأوجبه أحمد على الرجال، وجعله مالك وأبو حنيفة سنة؛ والراجح أنه في حق الرجال سنة مؤكدة من شعائر الإسلام لا ينبغي تركها. ولا يختص بوقت، والأفضل تعجيله في الصغر؛ ومن أسلم كبيرًا وخاف على نفسه سقط عنه.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: «الْفِطْرَةُ خَمْسٌ - أَوْ خَمْسٌ مِنَ الْفِطْرَةِ - الْخِتَانُ، وَالِاسْتِحْدَادُ، وَتَقْلِيمُ الْأَظْفَارِ، وَنَتْفُ الْإِبِطِ، وَقَصُّ الشَّارِبِ»","src":"رواه مسلم ٢٥٧، والبخاري ٥٨٩١","links":[{"book":"mt_muslim","num":257,"id":"h257"},{"book":"mt_bukhari","num":5891,"id":"h5891"}]},{"t":"quote","text":"عَنْ أَبِي هُرَيْرَةَ ـ رضى الله عنه ـ قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم « اخْتَتَنَ إِبْرَاهِيمُ ـ عَلَيْهِ السَّلاَمُ ـ وَهْوَ ابْنُ ثَمَانِينَ سَنَةً بِالْقَدُّومِ»","src":"رواه البخاري ٣٣٥٦","links":[{"book":"mt_bukhari","num":3356,"id":"h3356"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَاخْتُلِفَ فِي وُجُوبِ الْخِتَانِ فَرَوَى الْإِمَامُ يَحْيَى عَنْ الْعِتْرَةِ وَالشَّافِعِيُّ وَكَثِيرٌ مِنْ الْعُلَمَاءِ أَنَّهُ وَاجِبٌ فِي حَقِّ الرِّجَالِ وَالنِّسَاءِ. وَعِنْدَ مَالِكٍ وَأَبِي حَنِيفَةَ وَالْمُرْتَضَى، قَالَ النَّوَوِيُّ: وَهُوَ قَوْلُ أَكْثَرِ الْعُلَمَاءِ أَنَّهُ سُنَّةٌ فِيهِمَا","src":"نيل الأوطار","loc":"١/١٤٥","pre":"قال الشوكاني:"},{"t":"qawl","label":"القول الأول","text":"أنه واجب على الرجال والنساء، وهو مذهب الشافعي."},{"t":"qawl","label":"القول الثاني","text":"أنه واجب على الرجال، مَكرُمة في حق النساء، وهو مذهب أحمد."},{"t":"quote","text":"فَأَمَّا الْخِتَانُ فَوَاجِبٌ عَلَى الرِّجَالِ، وَمَكْرُمَةٌ فِي حَقِّ النِّسَاءِ، وَلَيْسَ بِوَاجِبٍ عَلَيْهِنَّ. هَذَا قَوْلُ كَثِيرٍ مِنْ أَهْلِ الْعِلْمِ","src":"المغني","loc":"١/٦٤","pre":"قال ابن قدامة:"},{"t":"quote","text":"وَالدَّلِيلُ عَلَى وُجُوبِهِ: أَنَّ سَتْرَ الْعَوْرَةِ وَاجِبٌ، فَلَوْلَا أَنَّ الْخِتَانَ وَاجِبٌ لَمْ يَجُزْ هَتْكُ حُرْمَةِ الْمَخْتُونِ بِالنَّظَرِ إلَى عَوْرَتِهِ مِنْ أَجْلِهِ؛ وَلِأَنَّهُ مِنْ شِعَارِ الْمُسْلِمِينَ، فَكَانَ وَاجِبًا، كَسَائِرِ شِعَارِهِمْ","src":"المغني","loc":"١/٦٤","pre":"ودليلهم:"},{"t":"qawl","label":"القول الثالث","text":"أنه سنة في الرجال والنساء، وهو مذهب مالك وأبي حنيفة، وقول أكثر العلماء كما حكاه النووي."},{"t":"h","text":"الترجيح","k":"r"},{"t":"quote","text":"وَالْحَقُّ أَنَّهُ لَمْ يَقُمْ دَلِيلٌ صَحِيحٌ يَدُلُّ عَلَى الْوُجُوبِ وَالْمُتَيَقَّنُ السُّنِّيَّةُ كَمَا فِي حَدِيثِ: (خَمْسٌ مِنْ الْفِطْرَةِ) وَنَحْوِهِ، وَالْوَاجِبُ الْوُقُوفُ عَلَى الْمُتَيَقَّنِ إلَى أَنْ يَقُومَ مَا يُوجِبُ الِانْتِقَالَ عَنْهُ","src":"نيل الأوطار","loc":"١/١٤٦","pre":"قال الشوكاني بعد أن ناقش أدلة الأقوال:"},{"t":"p","text":"فالختان في حق الرجال سنة مؤكدة من خصال الفطرة وشعائر المسلمين، فلا ينبغي التهاون به، ومن أخذ بقول من أوجبه احتياطًا فقد أحسن."},{"t":"h","text":"وقت الختان"},{"t":"quote","text":"وَأَوْرَدَ الْمُصَنِّفُ الْحَدِيثَ فِي هَذَا الْبَابِ لِلِاسْتِدْلَالِ بِهِ عَلَى أَنَّ مُدَّةَ الْخِتَانِ لَا تَخْتَصُّ بِوَقْتٍ مُعَيَّنٍ، وَهُوَ مَذْهَبُ الْجُمْهُورِ وَلَيْسَ بِوَاجِبٍ فِي حَالِ الصِّغَرِ","src":"نيل الأوطار","loc":"١/١٤٥"},{"t":"quote","text":"عَنْ سَعِيدِ بْنِ جُبَيْرٍ، قَالَ سُئِلَ ابْنُ عَبَّاسٍ مِثْلُ مَنْ أَنْتَ حِينَ قُبِضَ النَّبِيُّ صلى الله عليه وسلم قَالَ أَنَا يَوْمَئِذٍ مَخْتُونٌ. قَالَ وَكَانُوا لاَ يَخْتِنُونَ الرَّجُلَ حَتَّى يُدْرِكَ","src":"رواه البخاري ٦٢٩٩","links":[{"book":"mt_bukhari","num":6299,"id":"h6299"}]},{"t":"tanbih","items":[{"t":"quote","text":"وَإِنْ أَسْلَمَ رَجُلٌ كَبِيرٌ فَخَافَ عَلَى نَفْسِهِ مِنْ الْخِتَانِ سَقَطَ عَنْهُ؛ لِأَنَّ الْغُسْلَ وَالْوُضُوءَ وَغَيْرَهُمَا يَسْقُطُ إذَا خَافَ عَلَى نَفْسِهِ مِنْهُ، فَهَذَا أَوْلَى","src":"المغني","loc":"١/٦٤","pre":"قال ابن قدامة:"}]}],"refs":["مسلم ٢٥٧، والبخاري ٥٨٩١","البخاري ٣٣٥٦","نيل الأوطار (١/١٤٥)","المغني (١/٦٤)","نيل الأوطار (١/١٤٦)","البخاري ٦٢٩٩"],"related":["خصال الفطرة ومدة تركها"],"alts":["ختان الكبير","ختان المولود","هل الختان واجب"]},{"n":17,"bab":"الطهارة","sub":"سنن الفطرة والسواك","title":"خصال الفطرة: حلق العانة ونتف الإبط وتقليم الأظفار، ومدة تركها","q":"ما خصال الفطرة؟ وما أقصى مدة يجوز فيها ترك حلق العانة ونتف الإبط وتقليم الأظفار وقص الشارب؟","short":"خصال الفطرة سنن مؤكدة، منها: قص الشارب، وإعفاء اللحية، والسواك، وحلق العانة، ونتف الإبط، وتقليم الأظفار؛ ولا يُترك شيء من ذلك أكثر من أربعين ليلة. ويجوز إزالة شعر الإبط والعانة بأي وسيلة، والأفضل ما وافق السنة: النتف في الإبط، والحلق في العانة.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"عَنْ عَائِشَةَ، قَالَتْ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «عَشْرٌ مِنَ الْفِطْرَةِ: قَصُّ الشَّارِبِ، وَإِعْفَاءُ اللِّحْيَةِ، وَالسِّوَاكُ، وَاسْتِنْشَاقُ الْمَاءِ، وَقَصُّ الْأَظْفَارِ، وَغَسْلُ الْبَرَاجِمِ، وَنَتْفُ الْإِبِطِ، وَحَلْقُ الْعَانَةِ، وَانْتِقَاصُ الْمَاءِ» قَالَ زَكَرِيَّا: قَالَ مُصْعَبٌ: وَنَسِيتُ الْعَاشِرَةَ إِلَّا أَنْ تَكُونَ الْمَضْمَضَةَ","src":"رواه مسلم ٢٦١، وأبو داود ٥٣، والترمذي ٢٧٥٧","links":[{"book":"mt_muslim","num":261,"id":"h261"},{"book":"mt_abudawud","num":53,"id":"h53"},{"book":"mt_tirmidhi","num":2757,"id":"h2757"}]},{"t":"quote","text":"عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ: - قَالَ أَنَسٌ - «وُقِّتَ لَنَا فِي قَصِّ الشَّارِبِ، وَتَقْلِيمِ الْأَظْفَارِ، وَنَتْفِ الْإِبِطِ، وَحَلْقِ الْعَانَةِ، أَنْ لَا نَتْرُكَ أَكْثَرَ مِنْ أَرْبَعِينَ لَيْلَةً»","src":"رواه مسلم ٢٥٨، وابن ماجه ٢٩٥","links":[{"book":"mt_muslim","num":258,"id":"h258"},{"book":"mt_ibnmajah","num":295,"id":"h295"}]},{"t":"h","text":"معنى الفطرة"},{"t":"quote","text":"وَالْمُرَادُ بِقَوْلِهِ: (خَمْسٌ مِنْ الْفِطْرَةِ) فِي حَدِيث الْبَابِ أَنَّ هَذِهِ الْأَشْيَاءَ إذَا فُعِلَتْ اتَّصَفَ فَاعِلُهَا بِالْفِطْرَةِ الَّتِي فَطَرَ اللَّهُ الْعِبَادَ عَلَيْهَا وَحَثَّهُمْ عَلَيْهَا وَاسْتَحَبَّهَا لَهُمْ لِيَكُونُوا عَلَى أَكْمَلِ الصِّفَاتِ وَأَشْرَفِهَا صُورَةً","src":"نيل الأوطار","loc":"١/١٤١","pre":"قال الشوكاني:"},{"t":"h","text":"كيفية الإزالة"},{"t":"quote","text":"وَالِاسْتِحْدَادُ: حَلْقُ الْعَانَةِ. وَهُوَ مُسْتَحَبٌّ؛ لِأَنَّهُ مِنْ الْفِطْرَةِ، وَيَفْحُشُ بِتَرْكِهِ، فَاسْتُحِبَّتْ إزَالَتُهُ، وَبِأَيِّ شَيْءٍ أَزَالَهُ صَاحِبُهُ فَلَا بَأْسَ؛ لِأَنَّ الْمَقْصُودَ إزَالَتُهُ","src":"المغني","loc":"١/٦٤","pre":"قال ابن قدامة:"},{"t":"quote","text":"وَنَتْفُ الْإِبْطِ سُنَّةٌ؛ لِأَنَّهُ مِنْ الْفِطْرَةِ، وَيَفْحُشُ بِتَرْكِهِ. وَإِنْ أَزَالَ الشَّعْرَ بِالْحَلْقِ أَوْ النُّورَةِ جَازَ، وَنَتْفُهُ أَفْضَلُ لِمُوَافَقَتِهِ الْخَبَرَ","src":"المغني","loc":"١/٦٥","pre":"وقال:"},{"t":"quote","text":"وَيُسْتَحَبُّ تَقْلِيمُ الْأَظْفَارِ؛ لِأَنَّهُ مِنْ الْفِطْرَةِ، وَيَتَفَاحَشُ إذَا تَرَكَهَا، وَرُبَّمَا حَكَّ بِهِ الْوَسَخَ، فَيَجْتَمِعُ تَحْتَهَا مِنْ الْمَوَاضِعِ الْمُنْتِنَةِ، فَتَصِيرُ رَائِحَةُ ذَلِكَ فِي رُءُوسِ الْأَصَابِعِ. وَرُبَّمَا مَنَعَ وُصُولَ الطَّهَارَةِ إلَى مَا تَحْتَهُ","src":"المغني","loc":"١/٦٥","pre":"وقال:"},{"t":"h","text":"الخلاصة","k":"r"},{"t":"p","text":"هذه الخصال سنن مؤكدة، وحديث أنس رضي الله عنه حدّ أقصى المدة بأربعين ليلة، فلا ينبغي أن تُترك أكثر من ذلك؛ والأفضل تعاهدها كلما طالت، ولا سيما يوم الجمعة."},{"t":"tanbih","items":[{"t":"p","text":"لا يتوقف على هذه الخصال صحة الوضوء ولا الصلاة، إلا إذا كان تحت الأظفار ما يمنع وصول الماء إلى البشرة، كما أشار إليه ابن قدامة في كلامه المنقول."}]}],"refs":["مسلم ٢٦١، وأبو داود ٥٣، والترمذي ٢٧٥٧","مسلم ٢٥٨، وابن ماجه ٢٩٥","نيل الأوطار (١/١٤١)","المغني (١/٦٤)","المغني (١/٦٥)"],"related":["حكم الختان ووقته","إعفاء اللحية وقص الشارب"],"alts":["مدة حلق العانة","تقليم الأظفار","سنن الفطرة"]},{"n":18,"bab":"الطهارة","sub":"سنن الفطرة والسواك","title":"إعفاء اللحية وقص الشارب","q":"ما حكم حلق اللحية أو تقصيرها؟ وما الأخذ مما زاد على القبضة؟ وما السنة في الشارب: القص أم الحلق؟","short":"حلق اللحية وتقصيرها عن القبضة لا يجوز في المذاهب الأربعة، والمأمور به إعفاؤها؛ وأما ما زاد على القبضة ففيه خلاف: فأجاز أخذه جماعة — منهم ابن عمر رضي الله عنهما والحنفية — واستحب آخرون تركها على حالها. وأما الشارب فالسنة قصّه حتى يبدو طرف الشفة، وذهب جماعة إلى أن إحفاءه أفضل.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"عَنِ ابْنِ عُمَرَ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ «خَالِفُوا الْمُشْرِكِينَ، وَفِّرُوا اللِّحَى، وَأَحْفُوا الشَّوَارِبَ». وَكَانَ ابْنُ عُمَرَ إِذَا حَجَّ أَوِ اعْتَمَرَ قَبَضَ عَلَى لِحْيَتِهِ، فَمَا فَضَلَ أَخَذَهُ","src":"رواه البخاري ٥٨٩٢","links":[{"book":"mt_bukhari","num":5892,"id":"h5892"}]},{"t":"quote","text":"عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «جُزُّوا الشَّوَارِبَ، وَأَرْخُوا اللِّحَى خَالِفُوا الْمَجُوسَ»","src":"رواه مسلم ٢٦٠","links":[{"book":"mt_muslim","num":260,"id":"h260"}]},{"t":"h","text":"المسألة الأولى: حلق اللحية وتقصيرها"},{"t":"quote","text":"وأما تقصير اللحية بحيث تصير قصيرة من القبضة فغير جائز في المذاهب الأربعة، وكذلك كل في الدر المختار في الصيام وترد شهادة مرتكب هذا الفعل","src":"العرف الشذي","loc":"٤/١٦٢","pre":"قال الشيخ أنور شاه الكشميري:"},{"t":"h","text":"المسألة الثانية: الأخذ مما زاد على القبضة"},{"t":"qawl","label":"القول الأول","text":"يجوز أخذ ما زاد على القبضة، وهو فعل ابن عمر رضي الله عنهما وجماعة من التابعين، والمختار عند الحنفية."},{"t":"qawl","label":"القول الثاني","text":"يُكره الأخذ منها مطلقًا، وتُترك على حالها، وهو اختيار النووي."},{"t":"quote","text":"قال الغزالي: اختلف السلف فيما زاد من اللحية، فقيل: لا بأس أن يقبض عليها ويقص ما تحت القبضة، كان ابن عمر يفعله، ثم جماعة من التابعين، والأمر في هذا قريب لأن الطول المفرط قد يشوه الخلقة، قال النووي: والصحيح كراهة الأخذ منها مطلقًا ويتركها على حالها كيف كانت لحديث أعفوا اللحى، وأما حديث عمرو بن عشيب بسنده أن النبي صلى الله عليه وسلم كان يأخذ من لحيته، فرواه الترمذي بإسناد ضعيف لا يحتج به، هكذا في البذل، وفي الدر المختار: لا بأس بأخذ أطراف اللحية والسنة فيها القبضة، قال ابن عابدين: كذا ذكره محمد في كتاب الآثار عن الإمام، قال: وبه نأخذ، انتهى","src":"الكوكب الدري على جامع الترمذي","loc":"٣/٤٠٢","pre":"وفي «الكوكب الدري» من شروح الحنفية:"},{"t":"quote","text":"وأما الذي زائد مسترسل من القبضة فقيل: الأولى الترك، قيل: الأولى القصر، والمختار القصر ولي في هذا الأولوية عبارة محمد في كتاب الآثار","src":"العرف الشذي","loc":"٤/١٦٢","pre":"وقال الكشميري:"},{"t":"h","text":"المسألة الثالثة: الشارب"},{"t":"quote","text":"وَقَدْ اخْتَلَفَ النَّاسُ فِي حَدِّ مَا يُقَصُّ مِنْ الشَّارِبِ، وَقَدْ ذَهَبَ كَثِيرٌ مِنْ السَّلَفِ إلَى اسْتِئْصَالِهِ وَحَلْقِهِ لِظَاهِرِ قَوْلِهِ: (أَحْفُوا وَانْهَكُوا) وَهُوَ قَوْلُ الْكُوفِيِّينَ، وَذَهَبَ كَثِيرٌ مِنْهُمْ إلَى مَنْعِ الْحَلْقِ وَالِاسْتِئْصَالِ، وَإِلَيْهِ ذَهَبَ مَالِكٌ وَكَانَ يَرَى تَأْدِيبَ مَنْ حَلَقَهُ. وَرَوَى عَنْهُ ابْنُ الْقَاسِمِ أَنَّهُ قَالَ: إحْفَاءُ الشَّارِبِ مُثْلَةً. قَالَ النَّوَوِيُّ: الْمُخْتَارُ أَنَّهُ يَقُصُّ حَتَّى يَبْدُوَ طَرَفُ الشَّفَةِ وَلَا يُحْفِيهِ مِنْ أَصْلِهِ، قَالَ: وَأَمَّا رِوَايَةُ: (أَحْفُوا الشَّوَارِبَ) فَمَعْنَاهُ أَحْفُوا مَا طَالَ عَنْ الشَّفَتَيْنِ، وَكَذَلِكَ قَالَ مَالِكٌ فِي الْمُوَطَّإِ يُؤْخَذُ مِنْ الشَّارِبِ حَتَّى يَبْدُوَ أَطْرَافُ الشَّفَةِ، قَالَ ابْنُ الْقَيِّمِ: وَأَمَّا أَبُو حَنِيفَةَ وَزُفَرُ وَأَبُو يُوسُفَ وَمُحَمَّدٌ. فَكَانَ مَذْهَبُهُمْ فِي شَعْرِ الرَّأْسِ وَالشَّوَارِبِ أَنَّ الْإِحْفَاءَ أَفْضَلُ مِنْ التَّقْصِيرِ","src":"نيل الأوطار","loc":"١/١٤٨","pre":"قال الشوكاني:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الواجب إعفاء اللحية، وحلقها أو تقصيرها عن القبضة محرّم باتفاق المذاهب الأربعة كما نقله الشيخ الكشميري. وأما ما زاد على القبضة فالأمر فيه واسع: فمن أخذه فله سلف من الصحابة، ومن تركه على حاله فقد وافق ظاهر الأمر بالإعفاء. وأما الشارب فكلٌّ من القص والإحفاء ثابت، والمقصود ألا يطول حتى يغطي الشفة."}],"refs":["البخاري ٥٨٩٢","مسلم ٢٦٠","العرف الشذي (٤/١٦٢)","الكوكب الدري على جامع الترمذي (٣/٤٠٢)","نيل الأوطار (١/١٤٨)"],"related":["خصال الفطرة","الخضاب بالسواد"],"alts":["حلق اللحية","تقصير اللحية","الأخذ من اللحية","حلق الشارب"]},{"n":19,"bab":"الطهارة","sub":"سنن الفطرة والسواك","title":"صبغ الشيب، والخضاب بالسواد","q":"هل يُستحب صبغ الشيب؟ وما حكم صبغ الشعر أو اللحية بالسواد؟","short":"يُستحب تغيير الشيب بالحناء والكتم ونحوهما مما ليس سوادًا خالصًا؛ وأما الخضاب بالسواد فقد نهى عنه النبي ﷺ، فحرّمه جماعة وكرهه آخرون، ورخّص فيه بعضهم؛ والراجح اجتنابه، ويُستثنى عند الحنفية الغازي ليهابه العدو.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"إِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ « إِنَّ الْيَهُودَ وَالنَّصَارَى لاَ يَصْبُغُونَ، فَخَالِفُوهُمْ»","src":"رواه البخاري ٣٤٦٢، ومسلم ٢١٠٣","pre":"عن أبي هريرة رضي الله عنه:","links":[{"book":"mt_bukhari","num":3462,"id":"h3462"},{"book":"mt_muslim","num":2103,"id":"h2103"}]},{"t":"quote","text":"عَنْ جَابِرِ بْنِ عَبْدِ اللهِ، قَالَ: أُتِيَ بِأَبِي قُحَافَةَ يَوْمَ فَتْحِ مَكَّةَ وَرَأْسُهُ وَلِحْيَتُهُ كَالثَّغَامَةِ بَيَاضًا، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «غَيِّرُوا هَذَا بِشَيْءٍ، وَاجْتَنِبُوا السَّوَادَ»","src":"رواه مسلم ٢١٠٢، وأبو داود ٤٢٠٤، والنسائي ٥٠٧٦","links":[{"book":"mt_muslim","num":2102,"id":"h2102-2"},{"book":"mt_abudawud","num":4204,"id":"h4204"},{"book":"mt_nasai","num":5076,"id":"h5076"}]},{"t":"h","text":"أقوال العلماء في الخضاب بالسواد"},{"t":"qawl","label":"القول الأول","text":"التحريم، وهو ما صوّبه النووي من الشافعية."},{"t":"quote","text":"قَالَ النَّوَوِيُّ: وَالصَّحِيحُ بَلْ الصَّوَابُ أَنَّهُ حَرَامٌ يَعْنِي الْخِضَابَ بِالسَّوَادِ، وَمِمَّنْ صَرَّحَ بِهِ صَاحِبُ الْحَاوِي انْتَهَى","src":"نيل الأوطار","loc":"١/١٥١"},{"t":"qawl","label":"القول الثاني","text":"الكراهة، وهو مذهب الحنابلة، وقول عامة مشايخ الحنفية إذا كان للزينة."},{"t":"quote","text":"وَيُكْرَهُ الْخِضَابُ بِالسَّوَادِ. قِيلَ لِأَبِي عَبْدِ اللَّهِ: تَكْرَهُ الْخِضَابَ بِالسَّوَادِ؟ قَالَ: إي وَاَللَّهِ. قَالَ: «وَجَاءَ أَبُو بَكْرٍ بِأَبِيهِ إلَى رَسُولِ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - وَرَأْسُهُ وَلِحْيَتُهُ كَالثَّغَامَةِ بَيَاضًا، فَقَالَ رَسُولُ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - غَيِّرُوهُمَا وَجَنِّبُوهُ السَّوَادَ» . وَرَوَى أَبُو دَاوُد، بِإِسْنَادِهِ عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ مَرْفُوعًا «يَكُونُ قَوْمٌ فِي آخِرِ الزَّمَانِ يُخَضِّبُونَ بِالسَّوَادِ كَحَوَاصِلِ الْحَمَامِ، لَا يَرِيحُونَ رَائِحَةَ الْجَنَّةِ» . وَرَخَّصَ فِيهِ إِسْحَاقُ بْنُ رَاهْوَيْهِ لِلْمَرْأَةِ تَتَزَيَّنُ بِهِ لِزَوْجِهَا","src":"المغني","loc":"١/٦٩","pre":"قال ابن قدامة:"},{"t":"quote","text":"قَالَ فِي الذَّخِيرَةِ: أَمَّا الْخِضَابُ بِالسَّوَادِ لِلْغَزْوِ، لِيَكُونَ أَهْيَبَ فِي عَيْنِ الْعَدُوِّ فَهُوَ مَحْمُودٌ بِالِاتِّفَاقِ وَإِنْ لِيُزَيِّنَ نَفْسَهُ لِلنِّسَاءِ فَمَكْرُوهٌ، وَعَلَيْهِ عَامَّةُ الْمَشَايِخِ، وَبَعْضُهُمْ جَوَّزَهُ بِلَا كَرَاهَةٍ رُوِيَ عَنْ أَبِي يُوسُفَ أَنَّهُ قَالَ: كَمَا يُعْجِبُنِي أَنْ تَتَزَيَّنَ لِي يُعْجِبُهَا أَنْ أَتَزَيَّنَ لَهَا","src":"الدر المختار مع رد المحتار","loc":"٦/٤٢٢","pre":"وقال ابن عابدين:"},{"t":"qawl","label":"القول الثالث","text":"الجواز، وهو مرويّ عن أبي يوسف، وعن جماعة من السلف أنهم خضبوا بالسواد."},{"t":"quote","text":"وَبَعْضُهُمْ بِالزَّعْفَرَانِ. وَخَضَّبَ جَمَاعَةٌ بِالسَّوَادِ، رُوِيَ ذَلِكَ عَنْ عُثْمَانَ وَالْحَسَنِ وَالْحُسَيْنِ ابْنَيْ عَلِيٍّ، وَعُقْبَةَ بْنِ عَامِرٍ وَابْنِ سِيرِينَ وَأَبِي بُرْدَةَ وَآخَرِينَ. قَالَ الطَّبَرِيُّ: الصَّوَابُ أَنَّ الْأَحَادِيثَ الْوَارِدَةَ عَنْ النَّبِيِّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - بِتَغْيِيرِ الشَّيْبِ، وَبِالنَّهْيِ عَنْهُ كُلُّهَا صَحِيحَةٌ وَلَيْسَ فِيهَا تَنَاقُضٌ بَلْ الْأَمْرُ بِالتَّغْيِيرِ لِمَنْ شَيْبُهُ كَشَيْبِ أَبِي قُحَافَةَ، وَالنَّهْيُ لِمَنْ لَهُ شَمْطٌ فَقَطْ قَالَ: وَاخْتِلَافُ السَّلَفِ فِي فِعْلِ الْأَمْرَيْنِ بِحَسَبِ اخْتِلَافِ أَحْوَالِهِمْ فِي ذَلِكَ مَعَ أَنَّ الْأَمْرَ وَالنَّهْيَ فِي ذَلِكَ لَيْسَ لِلْوُجُوبِ بِالْإِجْمَاعِ، وَلِهَذَا لَمْ يُنْكِرْ بَعْضُهُمْ عَلَى بَعْضٍ","src":"نيل الأوطار","loc":"١/١٥٢","pre":"قال الشوكاني ناقلًا عن القاضي عياض والطبري:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الراجح اجتناب الخضاب بالسواد؛ لصريح أمر النبي ﷺ: «وجنبوه السواد». وقد صرّح العلامة عبد الحي اللكنوي من محققي الحنفية بأن الخضاب بالسواد الخالص غير جائز، واحتجّ بحديث ابن عباس رضي الله عنهما في الذين يخضبون بالسواد في آخر الزمان، ثم أجاب عمّن رُوي عنه فعله فقال:"},{"t":"quote","text":"وجنح ابن الجوزي في \"العلل المتناهية\" إلى تضعيفه مستنداً بما رُوي أن سعداً والحسين بن عليّ كانا يخضبان بالسواد، وليس بجيد بَأْسًا، وَإِنْ تَرَكَهُ أَبْيَضَ فَلا بَأْسَ بِذَلِكَ، كلُّ ذَلِكَ حَسَنٌ . 43 - بَابُ الْوَلِيِّ يَسْتَقْرِضُ مِنْ مَالِ الْيَتِيمِ 937 - أَخْبَرَنَا مَالِكٌ، أَخْبَرَنَا يَحْيَى بْنُ سَعِيدٍ قَالَ: سَمِعْتُ الْقَاسِمَ بْنَ مُحَمَّدٍ يَقُولُ: جَاءَ رَجُلٌ إِلَى ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا فَقَالَ لَهُ: إِنَّ لِي يَتِيمًا وَلَهُ إِبِلٌ فَأَشْرَبُ مِنْ لَبَنِ إِبِلِهِ؟ قَالَ لَهُ ابن عباس: __________ فلعله لم يبلغهما الحديث، والكلام في بعض رواته ليس بحيث يُخرجه عن حيز الاحتجاج به، ومن ثمَّ عدّ ابن حجر المكي في \"الزواجر\" الخضاب بالسواد من الكبائر ويؤيده ما أخرجه الطبراني عن أبي الدرداء مرفوعاً: من خضب بالسواد سودّ الله وجهه يوم القيامة، وعند أحمد: وغيِّروا الشيب ولا تقربوا السواد. وأما ما في \"سنن ابن ماجه\" مرفوعاً: إن أحسن ما اختضبتم به هذا السواد أرغب لنسائكم وأهيب لكم في صدور أعدائكم، ففي سنده ضعفاء فلا يُعارِض الروايات الصحيحة، وأخذ منه بعض الفقهاء جوازه في الجهاد","src":"التعليق الممجد","loc":"٣/٤٦٣-٤٦٤"},{"t":"tanbih","items":[{"t":"p","text":"يُستحب تغيير الشيب بالحناء والكتم، أو بالصفرة؛ لأمر النبي ﷺ بمخالفة اليهود والنصارى في ذلك. وما خُلط فيه الحناء بالكتم فصار بين السواد والحمرة فليس من السواد الخالص."}]}],"refs":["البخاري ٣٤٦٢، ومسلم ٢١٠٣","مسلم ٢١٠٢، وأبو داود ٤٢٠٤، والنسائي ٥٠٧٦","نيل الأوطار (١/١٥١)","المغني (١/٦٩)","الدر المختار مع رد المحتار (٦/٤٢٢)","نيل الأوطار (١/١٥٢)","التعليق الممجد (٣/٤٦٣-٤٦٤)"],"related":["إعفاء اللحية وقص الشارب"],"alts":["صبغ الشعر بالأسود","الحناء للشيب","صبغ اللحية"]},{"n":20,"bab":"الطهارة","sub":"سنن الفطرة والسواك","title":"السواك: حكمه، ومواضعه، وللصائم بعد الزوال","q":"ما حكم السواك؟ ومتى يتأكد؟ وهل يُكره للصائم بعد الزوال؟","short":"السواك سنة مؤكدة باتفاق أهل العلم، ويتأكد عند الوضوء والصلاة والقيام من النوم وتغيّر الفم ودخول البيت؛ وهو مستحب للصائم في أول النهار وآخره على الراجح، وهو قول الجمهور، وكرهه الشافعي في المشهور عنه بعد الزوال.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"عَنْ أَبِي هُرَيْرَةَ ـ رضى الله عنه ـ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ « لَوْلاَ أَنْ أَشُقَّ عَلَى أُمَّتِي ـ أَوْ عَلَى النَّاسِ ـ لأَمَرْتُهُمْ بِالسِّوَاكِ مَعَ كُلِّ صَلاَةٍ»","src":"رواه البخاري ٨٨٧، ومسلم ٢٥٢","links":[{"book":"mt_bukhari","num":887,"id":"h887"},{"book":"mt_muslim","num":252,"id":"h252"}]},{"t":"quote","text":"عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ « السِّوَاكُ مَطْهَرَةٌ لِلْفَمِ مَرْضَاةٌ لِلرَّبِّ»","src":"رواه النسائي ٥","pre":"وعن عائشة رضي الله عنها:","links":[{"book":"mt_nasai","num":5,"id":"h5"}]},{"t":"h","text":"حكمه"},{"t":"quote","text":"أَكْثَرُ أَهْلِ الْعِلْمِ يَرَوْنَ السِّوَاكَ سُنَّةً غَيْرَ وَاجِبٍ، وَلَا نَعْلَمُ أَحَدًا قَالَ بِوُجُوبِهِ إلَّا إِسْحَاقَ وَدَاوُد؛ لِأَنَّهُ مَأْمُورٌ بِهِ، وَالْأَمْرُ يَقْتَضِي الْوُجُوبَ. وَقَدْ رَوَى أَبُو دَاوُد بِإِسْنَادِهِ، «أَنَّ النَّبِيَّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - أَمَرَ بِالْوُضُوءِ عِنْدَ كُلِّ صَلَاةٍ طَاهِرًا وَغَيْرَ طَاهِرٍ، فَلَمَّا شَقَّ ذَلِكَ عَلَيْهِ أَمَرَ بِالسِّوَاكِ عِنْدَ كُلِّ صَلَاةٍ» . وَلَنَا قَوْلُ النَّبِيِّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -: «لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي لَأَمَرْتهمْ بِالسِّوَاكِ عِنْدَ كُلِّ صَلَاةٍ» . مُتَّفَقٌ عَلَيْهِ، يَعْنِي لَأَمَرْتهمْ أَمْرَ إيجَابٍ؛ لِأَنَّ الْمَشَقَّةَ إنَّمَا تَلْحَقُ بِالْإِيجَابِ لَا بِالنَّدْبِ، وَهَذَا يَدُلُّ عَلَى أَنَّ الْأَمْرَ فِي حَدِيثِهِمْ أَمْرُ نَدْبٍ وَاسْتِحْبَابٍ، وَيَحْتَمِلُ أَنْ يَكُونَ ذَلِكَ وَاجِبًا فِي حَقِّ النَّبِيِّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - عَلَى الْخُصُوصِ، جَمْعًا بَيْنَ الْخَبَرَيْنِ، وَاتَّفَقَ أَهْلُ الْعِلْمِ عَلَى أَنَّهُ سُنَّةٌ مُؤَكَّدَةٌ، لِحَثِّ النَّبِيِّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - وَمُوَاظَبَتِهِ عَلَيْهِ، وَتَرْغِيبِهِ فِيهِ وَنَدْبِهِ إلَيْهِ، وَتَسْمِيَتِهِ إيَّاهُ مِنْ الْفِطْرَةِ فِيمَا رَوَيْنَا مِنْ الْحَدِيثِ","src":"المغني","loc":"١/٧١","pre":"قال ابن قدامة:"},{"t":"quote","text":"وَيَتَأَكَّدُ اسْتِحْبَابُهُ فِي مَوَاضِعَ ثَلَاثَةٍ: عِنْدَ الصَّلَاةِ؛ لِلْخَبَرِ الْأَوَّلِ. وَعِنْدَ الْقِيَامِ مِنْ النَّوْمِ؛ لِمَا رَوَى حُذَيْفَةُ، قَالَ: كَانَ رَسُولُ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - إذَا قَامَ مِنْ اللَّيْلِ يَشُوصُ فَاهُ بِالسِّوَاكِ. مُتَّفَقٌ عَلَيْهِ، يَعْنِي: يَغْسِلُهُ، يُقَالُ: شَاصَهُ، يَشُوصُهُ، وَمَاصَهُ: إذَا غَسَلَهُ، وَعَنْ عَائِشَةَ، - رَضِيَ اللَّهُ عَنْهَا - قَالَتْ: «كَانَ رَسُولُ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - لَا يَرْقُدُ مِنْ لَيْلٍ أَوْ نَهَارٍ فَيَسْتَيْقِظُ إلَّا تَسَوَّكَ قَبْلَ أَنْ يَتَوَضَّأَ.» رَوَاهُ أَبُو دَاوُد؛ وَلِأَنَّهُ إذَا نَامَ يَنْطَبِقُ فُوهُ فَتَتَغَيَّرُ رَائِحَتُهُ. وَعِنْدَ تَغَيُّرِ رَائِحَةِ فِيهِ بِمَأْكُولٍ أَوْ غَيْرِهِ؛ وَلِأَنَّ السِّوَاكَ مَشْرُوعٌ لِإِزَالَةِ رَائِحَتِهِ وَتَطْيِيبِهِ","src":"المغني","loc":"١/٧١","pre":"وقال:"},{"t":"h","text":"السواك للصائم بعد الزوال"},{"t":"qawl","label":"القول الأول","text":"يُكره للصائم بعد الزوال، وهو قول الشافعي في المشهور عنه، وإسحاق وأبي ثور، وإحدى الروايتين عن أحمد."},{"t":"qawl","label":"القول الثاني","text":"لا يُكره، بل يُستحب في أول النهار وآخره، وهو قول مالك وأصحاب الرأي، والرواية الأخرى عن أحمد."},{"t":"quote","text":"قَالَ ابْنُ عَقِيلٍ لَا يَخْتَلِفُ الْمَذْهَبُ أَنَّهُ لَا يُسْتَحَبُّ لِلصَّائِمِ السِّوَاكُ بَعْدَ الزَّوَالِ، وَهَلْ يُكْرَهُ؟ عَلَى رِوَايَتَيْنِ: إحْدَاهُمَا يُكْرَهُ، وَهُوَ قَوْلُ الشَّافِعِيِّ، وَإِسْحَاقَ وَأَبِي ثَوْرٍ وَرُوِيَ ذَلِكَ عَنْ عُمَرَ وَعَطَاءٍ وَمُجَاهِدٍ لِمَا رُوِيَ عَنْ عُمَرَ - رَضِيَ اللَّهُ عَنْهُ - أَنَّهُ قَالَ: يَسْتَاكُ مَا بَيْنَهُ وَبَيْنَ الظُّهْرِ، وَلَا يَسْتَاكُ بَعْدَ ذَلِكَ. وَلِأَنَّ السِّوَاكَ إنَّمَا اُسْتُحِبَّ لِإِزَالَةِ رَائِحَةِ الْفَمِ، وَقَدْ قَالَ النَّبِيُّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -: «لَخُلُوفُ فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ مِنْ رِيحِ الْمِسْكِ» . قَالَ التِّرْمِذِيُّ: هَذَا حَدِيثٌ حَسَنٌ","src":"المغني","loc":"١/٧٢","pre":"قال ابن قدامة:"},{"t":"quote","text":"لَخُلُوفُ فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ تَعَالَى مِنْ رِيحِ الْمِسْكِ","src":"رواه البخاري ١٨٩٤، ومسلم ١١٥١","pre":"ودليل من كرهه قوله ﷺ:","links":[{"book":"mt_bukhari","num":1894,"id":"h1894"},{"book":"mt_muslim","num":1151,"id":"h1151"}]},{"t":"h","text":"الترجيح","k":"r"},{"t":"quote","text":"وَقَدْ نَقَلَ التِّرْمِذِيُّ أَنَّ الشَّافِعِيَّ قَالَ: لَا بَأْسَ بِالسِّوَاكِ لِلصَّائِمِ أَوَّلَ النَّهَارِ وَآخِرَهُ. وَاخْتَارَهُ جَمَاعَةٌ مِنْ أَصْحَابِهِ مِنْهُمْ: أَبُو شَامَةَ وَابْنُ عَبْدِ السَّلَامِ وَالنَّوَوِيُّ وَالْمُزَنِيِّ","src":"نيل الأوطار","loc":"١/١٣٩","pre":"الراجح استحبابه في أول النهار وآخره؛ لعموم الأحاديث. وقد نقل عن الشافعي نفسه ما يوافق ذلك؛ قال الشوكاني:"},{"t":"quote","text":"وَقَوْلُ أَبِي هُرَيْرَةَ مَعَ كَوْنِهِ لَا يَدُلُّ عَلَى الْمَطْلُوبِ لَا حُجَّةَ فِيهِ عَلَى أَنَّ فِيهِ عُمَرَ بْنَ قَيْسٍ وَهُوَ مَتْرُوكٌ، وَكَذَلِكَ حَدِيثُ عَلِيٍّ مَعَ ضَعْفِهِ لَمْ يُصَرِّحْ فِيهِ بِالرَّفْعِ، فَالْحَقُّ أَنَّهُ يُسْتَحَبُّ السِّوَاكُ لِلصَّائِمِ أَوَّلَ النَّهَارِ وَآخِرَهُ وَهُوَ مَذْهَبُ جُمْهُورِ الْأَئِمَّةِ","src":"نيل الأوطار","loc":"١/١٣٩","pre":"ثم قال:"},{"t":"tanbih","items":[{"t":"quote","text":"وَإِنْ اسْتَاكَ بِأُصْبُعِهِ أَوْ خِرْقَةٍ، فَقَدْ قِيلَ: لَا يُصِيبُ السُّنَّةَ؛ لِأَنَّ الشَّرْعَ لَمْ يَرِدْ بِهِ، وَلَا يَحْصُلُ الْإِنْقَاءُ بِهِ حُصُولَهُ بِالْعُودِ، وَالصَّحِيحُ أَنَّهُ يُصِيبُ بِقَدْرِ مَا يَحْصُلُ مِنْ الْإِنْقَاءِ، وَلَا يُتْرَكُ الْقَلِيلُ مِنْ السُّنَّةِ لِلْعَجْزِ عَنْ كَثِيرِهَا","src":"المغني","loc":"١/٧٢","pre":"من لم يجد السواك فاستاك بأصبعه أو بالفرشاة؛ قال ابن قدامة:"}]}],"refs":["البخاري ٨٨٧، ومسلم ٢٥٢","النسائي ٥","المغني (١/٧١)","المغني (١/٧٢)","البخاري ١٨٩٤، ومسلم ١١٥١","نيل الأوطار (١/١٣٩)"],"related":["خصال الفطرة"],"alts":["السواك في رمضان","فرشاة الأسنان والسواك","السواك عند الصلاة"]}]};
